## Building Custom Configuration Sources

### Source Trait Implementation

**Example: HTTP Source**:
```rust
use config_rs::{Source, Result, Value};
use serde_json::Value as JsonValue;

pub struct HttpSource {
    url: String,
    priority: u32,
}

impl HttpSource {
    pub fn new(url: impl Into<String>) -> Self {
        Self {
            url: url.into(),
            priority: 50,
        }
    }

    pub fn priority(mut self, priority: u32) -> Self {
        self.priority = priority;
        self
    }
}

impl Source for HttpSource {
    fn load(&self) -> Result<Value> {
        let response = reqwest::get(&self.url)
            .map_err(|e| Error::source(format!("Failed to fetch from {}", self.url), e))?
            .json::<JsonValue>()
            .map_err(|e| Error::source("Failed to parse JSON", e))?;

        // Convert JSON to config Value
        Ok(serde_json::from_value(response)?)
    }

    fn name(&self) -> &str {
        "http"
    }

    fn priority(&self) -> u32 {
        self.priority
    }
}
```

**Usage**:
```rust
#[derive(Config)]
#[config(source = HttpSource::new("http://config-server/config.json"))]
struct Settings {
    port: u16,
}
```

---

### Custom Source with Caching

**Example: Cached HTTP Source**:
```rust
use std::sync::{Arc, RwLock};
use std::time::{Duration, Instant};

pub struct CachedHttpSource {
    url: String,
    cache_duration: Duration,
    cache: Arc<RwLock<Option<(Value, Instant)>>>,
}

impl CachedHttpSource {
    pub fn new(url: impl Into<String>) -> Self {
        Self {
            url: url.into(),
            cache_duration: Duration::from_secs(300), // 5 minutes
            cache: Arc::new(RwLock::new(None)),
        }
    }

    pub fn cache_duration(mut self, duration: Duration) -> Self {
        self.cache_duration = duration;
        self
    }
}

impl Source for CachedHttpSource {
    fn load(&self) -> Result<Value> {
        // Check cache
        {
            let cache = self.cache.read().unwrap();
            if let Some((value, timestamp)) = cache.as_ref() {
                if timestamp.elapsed() < self.cache_duration {
                    return Ok(value.clone());
                }
            }
        }

        // Fetch new value
        let value = self.fetch()?;

        // Update cache
        {
            let mut cache = self.cache.write().unwrap();
            *cache = Some((value.clone(), Instant::now()));
        }

        Ok(value)
    }

    fn name(&self) -> &str {
        "cached_http"
    }
}
```

---

### Custom Source with Authentication

**Example: Authenticated API Source**:
```rust
pub struct AuthenticatedApiSource {
    url: String,
    api_key: String,
}

impl AuthenticatedApiSource {
    pub fn new(url: impl Into<String>, api_key: impl Into<String>) -> Self {
        Self {
            url: url.into(),
            api_key: api_key.into(),
        }
    }
}

impl Source for AuthenticatedApiSource {
    fn load(&self) -> Result<Value> {
        let response = reqwest::Client::new()
            .get(&self.url)
            .header("Authorization", format!("Bearer {}", self.api_key))
            .send()
            .map_err(|e| Error::source("HTTP request failed", e))?
            .json::<JsonValue>()
            .map_err(|e| Error::source("Failed to parse JSON", e))?;

        Ok(serde_json::from_value(response)?)
    }

    fn name(&self) -> &str {
        "authenticated_api"
    }
}
```

