## Hot Reload Implementation

### File Watching with Notify

**Basic file watching**:
```rust
use notify::{Watcher, RecursiveMode, watcher};
use std::sync::mpsc::channel;

pub struct ConfigWatcher<T> {
    config: T,
    callback: Box<dyn Fn(&T) + Send>,
}

impl<T: Config> ConfigWatcher<T> {
    pub fn new(callback: Box<dyn Fn(&T) + Send>) -> Result<Self> {
        let config = T::load()?;

        Ok(Self {
            config,
            callback,
        })
    }

    pub fn watch(mut self, path: &str) -> Result<()> {
        let (tx, rx) = channel();

        let mut watcher = watcher(tx, Duration::from_millis(500))?;
        watcher.watch(path, RecursiveMode::NonRecursive)?;

        loop {
            match rx.recv() {
                Ok(event) => {
                    if let notify::DebouncedEvent::Write(_) = event {
                        self.reload()?;
                    }
                }
                Err(e) => {
                    eprintln!("Watch error: {:?}", e);
                }
            }
        }
    }

    fn reload(&mut self) -> Result<()> {
        match T::load() {
            Ok(new_config) => {
                self.config = new_config;
                (self.callback)(&self.config);
                Ok(())
            }
            Err(e) => {
                eprintln!("Failed to reload config: {}", e);
                eprintln!("Keeping old config");
                Err(e)
            }
        }
    }
}
```

---

### Debouncing

**Debounce file changes**:
```rust
use std::time::{Duration, Instant};

pub struct Debouncer {
    last_change: Arc<Mutex<Option<Instant>>>,
    debounce_duration: Duration,
}

impl Debouncer {
    pub fn new(debounce_duration: Duration) -> Self {
        Self {
            last_change: Arc::new(Mutex::new(None)),
            debounce_duration,
        }
    }

    pub fn should_reload(&self) -> bool {
        let mut last = self.last_change.lock().unwrap();
        let now = Instant::now();

        if let Some(last_change) = *last {
            if now.duration_since(last_change) > self.debounce_duration {
                *last = Some(now);
                true
            } else {
                *last = Some(now);
                false
            }
        } else {
            *last = Some(now);
            true
        }
    }
}
```

---

### Error Handling on Reload

**Graceful error handling**:
```rust
pub struct ReloadHandler<T> {
    config: T,
    on_reload: Box<dyn Fn(&T)>,
    on_error: Box<dyn Fn(&Error)>,
}

impl<T: Config> ReloadHandler<T> {
    pub fn reload(&mut self) {
        match T::load() {
            Ok(new_config) => {
                self.config = new_config;
                (self.on_reload)(&self.config);
            }
            Err(e) => {
                (self.on_error)(&e);
                // Keep old config
            }
        }
    }
}
```

**Usage**:
```rust
let handler = ReloadHandler::new(
    |config| {
        println!("Config reloaded successfully");
    },
    |error| {
        eprintln!("Failed to reload config: {}", error);
    }
);

handler.watch("config.toml")?;
```

