## Example 2: Encrypted Matrix Multiplication

**Goal**: Perform matrix operations on encrypted data using batching.

```rust
use crypto_rs::{Context, Scheme, SecurityLevel};

fn main() -> crypto_rs::Result<()> {
    // Use CKKS for floating-point
    let ctx = Context::builder()
        .scheme(Scheme::CKKS)
        .security_level(SecurityLevel::Standard)
        .build()?;

    // 2x2 matrices (row-major encoding)
    // A = [[1, 2], [3, 4]]
    // B = [[5, 6], [7, 8]]
    let matrix_a = vec![1.0, 2.0, 3.0, 4.0];
    let matrix_b = vec![5.0, 6.0, 7.0, 8.0];

    // Encrypt matrices
    let encrypted_a = ctx.encrypt_batch(matrix_a)?;
    let encrypted_b = ctx.encrypt_batch(matrix_b)?;

    // Matrix multiplication using rotations
    // C[0,0] = A[0,0]*B[0,0] + A[0,1]*B[1,0] = 1*5 + 2*7 = 19
    // C[0,1] = A[0,0]*B[0,1] + A[0,1]*B[1,1] = 1*6 + 2*8 = 22
    // C[1,0] = A[1,0]*B[0,0] + A[1,1]*B[1,0] = 3*5 + 4*7 = 43
    // C[1,1] = A[1,0]*B[0,1] + A[1,1]*B[1,1] = 3*6 + 4*8 = 50

    // Encrypted matrix multiplication
    let encrypted_c = encrypted_matrix_mul(&ctx, &encrypted_a, &encrypted_b)?;

    // Decrypt result
    let result: Vec<f64> = ctx.decrypt_batch(&encrypted_c)?;

    println!("Result matrix C:");
    println!("  [{:.1}, {:.1}]", result[0], result[1]);
    println!("  [{:.1}, {:.1}]", result[2], result[3]);
    // Expected: [[19, 22], [43, 50]]

    // Verify (allowing small floating-point errors)
    assert!((result[0] - 19.0).abs() < 0.1);
    assert!((result[1] - 22.0).abs() < 0.1);
    assert!((result[2] - 43.0).abs() < 0.1);
    assert!((result[3] - 50.0).abs() < 0.1);

    Ok(())
}

// Naive encrypted matrix multiplication
fn encrypted_matrix_mul(
    ctx: &Context,
    a: &Ciphertext,
    b: &Ciphertext,
) -> crypto_rs::Result<Ciphertext> {
    // For 2x2: C[i,j] = sum(A[i,k] * B[k,j]) over k

    // Diagonal method: multiply, rotate, sum
    let mut result = ctx.encrypt(0.0)?;

    // First diagonal: (no rotation)
    let diag0 = ctx.evaluator().mul_elementwise(a, b)?;
    result = &result + &diag0;

    // Second diagonal: rotate B by 1
    let b_rot1 = ctx.rotate(b, 1)?;
    let diag1 = ctx.evaluator().mul_elementwise(a, &b_rot1)?;
    result = &result + &diag1;

    // Sum columns to get final result
    // (Simplified - would need more rotations for larger matrices)
    Ok(result)
}
```

**What you learned**:
- Batch encoding for SIMD operations
- Matrix operations with rotations
- CKKS for floating-point arithmetic
- Handling approximate precision

**Run it**:
```bash
cargo run --example matrix_mul
```

