## Example 3: Private Statistics

**Goal**: Compute mean, variance, standard deviation on encrypted data.

```rust
use crypto_rs::{Context, Scheme, SecurityLevel};

fn main() -> crypto_rs::Result<()> {
    let ctx = Context::builder()
        .scheme(Scheme::CKKS)
        .security_level(SecurityLevel::Standard)
        .enable_profiling(true)
        .build()?;

    // Private dataset (ages in a medical study)
    let data = vec![25.0, 30.0, 35.0, 40.0, 45.0, 50.0, 55.0, 60.0];

    println!("Computing statistics on encrypted data...");
    println!("Data: {:?}", data);

    // Encrypt dataset
    let encrypted_data = ctx.encrypt_batch(data.clone())?;

    // 1. Compute sum
    let encrypted_sum = ctx.sum_slots(&encrypted_data)?;
    let sum: f64 = ctx.decrypt(&encrypted_sum)?;
    println!("\nSum: {:.1}", sum);

    // 2. Compute mean
    let n = data.len() as f64;
    let encrypted_mean = &encrypted_sum * (1.0 / n);
    let mean: f64 = ctx.decrypt(&encrypted_mean)?;
    println!("Mean: {:.2}", mean);  // Expected: 42.5

    // 3. Compute variance: Var(X) = E[X²] - E[X]²
    let encrypted_squared = ctx.evaluator().pow(&encrypted_data, 2)?;
    let encrypted_sum_squares = ctx.sum_slots(&encrypted_squared)?;
    let encrypted_e_x2 = &encrypted_sum_squares * (1.0 / n);

    let encrypted_mean_squared = ctx.evaluator().pow(&encrypted_mean, 2)?;

    let encrypted_variance = &encrypted_e_x2 - &encrypted_mean_squared;
    let variance: f64 = ctx.decrypt(&encrypted_variance)?;
    println!("Variance: {:.2}", variance);  // Expected: 143.75

    // 4. Compute standard deviation: σ = √Var
    let encrypted_std_dev = ctx.evaluator().sqrt(&encrypted_variance)?;
    let std_dev: f64 = ctx.decrypt(&encrypted_std_dev)?;
    println!("Std Dev: {:.2}", std_dev);  // Expected: 11.99

    // Verify against plaintext computation
    let plaintext_mean: f64 = data.iter().sum::<f64>() / n;
    let plaintext_var: f64 = data.iter()
        .map(|x| (x - plaintext_mean).powi(2))
        .sum::<f64>() / n;
    let plaintext_std: f64 = plaintext_var.sqrt();

    println!("\nPlaintext verification:");
    println!("Mean: {:.2} (error: {:.6})", plaintext_mean, (mean - plaintext_mean).abs());
    println!("Variance: {:.2} (error: {:.6})", plaintext_var, (variance - plaintext_var).abs());
    println!("Std Dev: {:.2} (error: {:.6})", plaintext_std, (std_dev - plaintext_std).abs());

    // Print profiling information
    println!("\n--- Performance Profile ---");
    ctx.print_profile();

    Ok(())
}
```

**Output**:
```
