## Example 4: Secure ML Inference

**Goal**: Run neural network inference on encrypted input.

```rust
use crypto_rs::{Context, Scheme, SecurityLevel};

// Simple neural network: 2 inputs → 3 hidden → 1 output
struct NeuralNetwork {
    // Layer 1: 2→3
    w1: [[f64; 3]; 2],  // weights
    b1: [f64; 3],      // biases

    // Layer 2: 3→1
    w2: [[f64; 1]; 3],
    b2: [f64; 1],
}

impl NeuralNetwork {
    fn new() -> Self {
        Self {
            w1: [[0.5, -0.3, 0.8], [0.2, 0.7, -0.4]],
            b1: [0.1, -0.2, 0.3],
            w2: [[0.6], [0.4], [-0.5]],
            b2: [0.0],
        }
    }

    // Plaintext inference (for verification)
    fn forward(&self, x: &[f64; 2]) -> f64 {
        // Layer 1: z1 = W1*x + b1
        let mut z1 = [0.0; 3];
        for j in 0..3 {
            z1[j] = self.b1[j];
            for i in 0..2 {
                z1[j] += self.w1[i][j] * x[i];
            }
        }

        // ReLU activation: a1 = max(0, z1)
        let a1: Vec<f64> = z1.iter().map(|&z| z.max(0.0)).collect();

        // Layer 2: z2 = W2*a1 + b2
        let mut z2 = self.b2[0];
        for j in 0..3 {
            z2 += self.w2[j][0] * a1[j];
        }

        // Sigmoid activation: output = σ(z2)
        sigmoid(z2)
    }
}

fn sigmoid(x: f64) -> f64 {
    1.0 / (1.0 + (-x).exp())
}

// Encrypted inference
fn encrypted_forward(
    ctx: &Context,
    model: &NeuralNetwork,
    encrypted_x: &Ciphertext,
) -> crypto_rs::Result<Ciphertext> {
    // Layer 1
    let mut encrypted_z1 = ctx.encrypt_batch(vec![0.0; 3])?;

    // Compute z1 = W1*x + b1
    for j in 0..3 {
        // Add bias
        encrypted_z1 = ctx.set_slot(&encrypted_z1, j, &ctx.encrypt(model.b1[j])?)?;

        // Multiply weights and sum
        for i in 0..2 {
            let x_i = ctx.extract_slot(encrypted_x, i)?;
            let weighted = &x_i * model.w1[i][j];
            encrypted_z1 = ctx.add_slot(&encrypted_z1, j, &weighted)?;
        }
    }

    // ReLU activation
    let encrypted_a1 = encrypted_relu(ctx, &encrypted_z1)?;

    // Layer 2
    let mut encrypted_z2 = ctx.encrypt(model.b2[0])?;

    for j in 0..3 {
        let a1_j = ctx.extract_slot(&encrypted_a1, j)?;
        let weighted = &a1_j * model.w2[j][0];
        encrypted_z2 = &encrypted_z2 + &weighted;
    }

    // Sigmoid activation (polynomial approximation)
    let encrypted_output = ctx.evaluator().sigmoid(&encrypted_z2)?;

    Ok(encrypted_output)
}

fn encrypted_relu(ctx: &Context, x: &Ciphertext) -> crypto_rs::Result<Ciphertext> {
    // ReLU(x) = max(0, x)
    let zero = ctx.encrypt(0.0)?;
    ctx.evaluator().max(x, &zero)
}

fn main() -> crypto_rs::Result<()> {
    let ctx = Context::builder()
        .scheme(Scheme::CKKS)
        .security_level(SecurityLevel::Standard)
        .computation_depth(5)  // 2 layers × 2 ops each + activation
        .build()?;

    let model = NeuralNetwork::new();

    // Test input
    let input = [0.5, -0.3];

    // Encrypt input
    let encrypted_input = ctx.encrypt_batch(vec![input[0], input[1]])?;

    println!("Running encrypted neural network inference...");

    // Encrypted inference
    let encrypted_output = encrypted_forward(&ctx, &model, &encrypted_input)?;

    // Decrypt result
    let encrypted_result: f64 = ctx.decrypt(&encrypted_output)?;

    // Plaintext inference (for verification)
    let plaintext_result = model.forward(&input);

    println!("\nInput: {:?}", input);
    println!("Encrypted inference result: {:.6}", encrypted_result);
    println!("Plaintext inference result: {:.6}", plaintext_result);
    println!("Error: {:.6}", (encrypted_result - plaintext_result).abs());

    // Should be very close (CKKS has small approximation error)
    assert!((encrypted_result - plaintext_result).abs() < 0.01);

    Ok(())
}
```

**Output**:
```
Running encrypted neural network inference...

Input: [0.5, -0.3]
Encrypted inference result: 0.523412
Plaintext inference result: 0.523408
Error: 0.000004
```

**What you learned**:
- Implementing neural network operations on encrypted data
- Activation functions in encrypted domain
- Verifying encrypted ML inference

**Run it**:
```bash
cargo run --example secure_ml
```

