## Example 5: Comparison of HE Schemes

**Goal**: Understand when to use BFV vs CKKS.

```rust
use crypto_rs::{Context, Scheme, SecurityLevel};

fn benchmark_scheme(scheme: Scheme) -> crypto_rs::Result<()> {
    println!("\n=== Benchmarking {:?} ===", scheme);

    let ctx = Context::builder()
        .scheme(scheme)
        .security_level(SecurityLevel::Standard)
        .enable_profiling(true)
        .build()?;

    // Test data
    let a = 42;
    let b = 20;

    // Encryption
    let start = std::time::Instant::now();
    let encrypted_a = ctx.encrypt(a)?;
    let encrypted_b = ctx.encrypt(b)?;
    let encrypt_time = start.elapsed();

    // Addition
    let start = std::time::Instant::now();
    let sum = &encrypted_a + &encrypted_b;
    let add_time = start.elapsed();

    // Multiplication
    let start = std::time::Instant::now();
    let product = &encrypted_a * &encrypted_b;
    let mul_time = start.elapsed();

    // Decryption
    let start = std::time::Instant::now();
    let result_sum: i64 = ctx.decrypt(&sum)?;
    let result_product: i64 = ctx.decrypt(&product)?;
    let decrypt_time = start.elapsed();

    // Results
    println!("Results:");
    println!("  {} + {} = {}", a, b, result_sum);
    println!("  {} × {} = {}", a, b, result_product);

    // Performance
    println!("\nPerformance:");
    println!("  Encryption: {:.2} ms", encrypt_time.as_secs_f64() * 1000.0);
    println!("  Addition: {:.2} ms", add_time.as_secs_f64() * 1000.0);
    println!("  Multiplication: {:.2} ms", mul_time.as_secs_f64() * 1000.0);
    println!("  Decryption: {:.2} ms", decrypt_time.as_secs_f64() * 1000.0);

    // Noise
    let (_, noise_sum) = ctx.decrypt_with_noise(&sum)?;
    let (_, noise_product) = ctx.decrypt_with_noise(&product)?;
    println!("\nNoise Budget:");
    println!("  After addition: {} bits", noise_sum.remaining);
    println!("  After multiplication: {} bits", noise_product.remaining);

    Ok(())
}

fn main() -> crypto_rs::Result<()> {
    println!("Homomorphic Encryption Scheme Comparison");
    println!("==========================================");

    // Benchmark BFV (integer arithmetic)
    benchmark_scheme(Scheme::BFV)?;

    // Benchmark CKKS (floating-point arithmetic)
    println!("\n=== Benchmarking CKKS (Floating-Point) ===");
    let ctx = Context::builder()
        .scheme(Scheme::CKKS)
        .security_level(SecurityLevel::Standard)
        .build()?;

    let a_f = 3.14159;
    let b_f = 2.71828;

    let encrypted_a = ctx.encrypt(a_f)?;
    let encrypted_b = ctx.encrypt(b_f)?;

    let sum_f = &encrypted_a + &encrypted_b;
    let product_f = &encrypted_a * &encrypted_b;

    let result_sum_f: f64 = ctx.decrypt(&sum_f)?;
    let result_product_f: f64 = ctx.decrypt(&product_f)?;

    println!("\nResults:");
    println!("  {:.5} + {:.5} = {:.5}", a_f, b_f, result_sum_f);
    println!("  {:.5} × {:.5} = {:.5}", a_f, b_f, result_product_f);
    println!("\nPrecision (error):");
    println!("  Addition error: {:.2e}", (result_sum_f - (a_f + b_f)).abs());
    println!("  Multiplication error: {:.2e}", (result_product_f - (a_f * b_f)).abs());

    println!("\n=== Recommendation ===");
    println!("Use BFV when:");
    println!("  ✓ Exact integer arithmetic required");
    println!("  ✓ Financial calculations (pennies matter)");
    println!("  ✓ Database queries");
    println!("\nUse CKKS when:");
    println!("  ✓ Floating-point arithmetic needed");
    println!("  ✓ Machine learning inference");
    println!("  ✓ Statistical analysis");
    println!("  ✓ Small approximation errors acceptable");

    Ok(())
}
```

**Output**:
```
