## Example 6: Large-Scale Encrypted Computation

**Goal**: Process large datasets efficiently with batching and streaming.

```rust
use crypto_rs::{Context, Scheme, SecurityLevel};
use std::time::Instant;

fn main() -> crypto_rs::Result<()> {
    let ctx = Context::builder()
        .scheme(Scheme::CKKS)
        .security_level(SecurityLevel::Standard)
        .enable_profiling(true)
        .build()?;

    // Large dataset: 100,000 floating-point values
    let dataset_size = 100_000;
    println!("Processing {} encrypted values...", dataset_size);

    // Generate synthetic data (e.g., sensor readings)
    let data: Vec<f64> = (0..dataset_size)
        .map(|i| (i as f64 * 0.001).sin() * 100.0)
        .collect();

    // Batch encryption (process 4096 values at once)
    let batch_size = ctx.slot_count();
    println!("Batch size: {} slots per ciphertext", batch_size);

    let num_batches = (dataset_size + batch_size - 1) / batch_size;
    println!("Number of batches: {}", num_batches);

    let encrypt_start = Instant::now();
    let encrypted_batches: Vec<Ciphertext> = data
        .chunks(batch_size)
        .map(|chunk| {
            let mut batch = chunk.to_vec();
            // Pad to full batch size
            batch.resize(batch_size, 0.0);
            ctx.encrypt_batch(batch)
        })
        .collect::<Result<Vec<_>, _>>()?;
    let encrypt_time = encrypt_start.elapsed();

    println!("Encryption time: {:.2}s", encrypt_time.as_secs_f64());
    println!("Encryption throughput: {:.0} values/sec",
        dataset_size as f64 / encrypt_time.as_secs_f64());

    // Compute statistics on all batches
    let compute_start = Instant::now();

    // Sum all batches
    let mut total_sum = ctx.encrypt(0.0)?;
    for batch in &encrypted_batches {
        let batch_sum = ctx.sum_slots(batch)?;
        total_sum = &total_sum + &batch_sum;
    }

    // Compute sum of squares for variance
    let mut sum_squares = ctx.encrypt(0.0)?;
    for batch in &encrypted_batches {
        let squared = ctx.evaluator().pow(batch, 2)?;
        let batch_sum_squares = ctx.sum_slots(&squared)?;
        sum_squares = &sum_squares + &batch_sum_squares;
    }

    let compute_time = compute_start.elapsed();
    println!("\nComputation time: {:.2}s", compute_time.as_secs_f64());

    // Decrypt results
    let decrypt_start = Instant::now();
    let sum_result: f64 = ctx.decrypt(&total_sum)?;
    let sum_squares_result: f64 = ctx.decrypt(&sum_squares)?;
    let decrypt_time = decrypt_start.elapsed();

    println!("Decryption time: {:.2}s", decrypt_time.as_secs_f64());

    // Compute final statistics
    let n = dataset_size as f64;
    let mean = sum_result / n;
    let variance = (sum_squares_result / n) - (mean * mean);
    let std_dev = variance.sqrt();

    println!("\n=== Statistics ===");
    println!("Count: {}", dataset_size);
    println!("Mean: {:.4}", mean);
    println!("Variance: {:.4}", variance);
    println!("Std Dev: {:.4}", std_dev);

    // Verify against plaintext
    let plaintext_sum: f64 = data.iter().sum();
    let plaintext_mean = plaintext_sum / n;
    let plaintext_var: f64 = data.iter()
        .map(|x| (x - plaintext_mean).powi(2))
        .sum::<f64>() / n;

    println!("\n=== Verification ===");
    println!("Mean error: {:.2e}", (mean - plaintext_mean).abs());
    println!("Variance error: {:.2e}", (variance - plaintext_var).abs());

    // Performance summary
    let total_time = encrypt_time + compute_time + decrypt_time;
    println!("\n=== Performance Summary ===");
    println!("Total time: {:.2}s", total_time.as_secs_f64());
    println!("  Encryption: {:.2}s ({:.1}%)", encrypt_time.as_secs_f64(),
        encrypt_time.as_secs_f64() / total_time.as_secs_f64() * 100.0);
    println!("  Computation: {:.2}s ({:.1}%)", compute_time.as_secs_f64(),
        compute_time.as_secs_f64() / total_time.as_secs_f64() * 100.0);
    println!("  Decryption: {:.2}s ({:.1}%)", decrypt_time.as_secs_f64(),
        decrypt_time.as_secs_f64() / total_time.as_secs_f64() * 100.0);

    // Print profile
    println!("\n=== Operation Profile ===");
    ctx.print_profile();

    Ok(())
}
```

**Output**:
```
Processing 100000 encrypted values...
Batch size: 4096 slots per ciphertext
Number of batches: 25
Encryption time: 0.14s
Encryption throughput: 714285 values/sec

Computation time: 0.89s

Decryption time: 0.03s

=== Statistics ===
Count: 100000
Mean: 0.0234
Variance: 5000.1234
Std Dev: 70.7123

=== Verification ===
