### Select Statement

```rust
use csp::channel;

fn main() {
    let rx1 = channel();
    let rx2 = channel();

    csp::spawn(|| rx1.send("from rx1"));
    csp::spawn(|| rx2.send("from rx2"));

    csp::select! {
        msg = rx1.recv() => println!("{}", msg.unwrap()),
        msg = rx2.recv() => println!("{}", msg.unwrap()),
