### Pipeline

```rust
use csp::channel;

fn main() {
    let (stage1_tx, stage1_rx) = channel().buffered(100).split();
    let (stage2_tx, stage2_rx) = channel().buffered(100).split();

    // Stage 1: Transform
    csp::spawn(|| {
        while let Ok(val) = stage1_rx.recv() {
            stage2_tx.send(val * 2).unwrap();
        }
    });

    // Stage 2: Filter
    csp::spawn(|| {
        while let Ok(val) = stage2_rx.recv() {
            if val % 3 == 0 {
                println!("{}", val);
            }
        }
    });

    // Input
    for i in 0..100 {
        stage1_tx.send(i).unwrap();
    }
}
```

