## Custom Validators

### When to Use Custom Validators

When built-in expectations don't cover your specific business rules, create custom validators.

### Simple Custom Validator

```rust
use dataval::{Validator, CustomExpectation};
use dataval::ExpectationResult;

let validator = Validator::new()
    .expect(CustomExpectation::new(
        "sum_less_than_million",
        "Sum of salaries must be less than 1 million",
        |data| {
            let salary_col = data.column("salary")?;
            let salaries = salary_col.f64()?;
            let sum: f64 = salaries.into_iter().filter_map(|v| v).sum();

            Ok(ExpectationResult {
                passed: sum < 1_000_000.0,
                expectation_name: "sum_less_than_million".to_string(),
                details: /* ... */,
            })
        }
    ));

let report = validator.validate(&df)?;
```

### Custom Validator with Details

```rust
use dataval::{Validator, CustomExpectation};
use dataval::ExpectationResult;
use dataval::ExpectationDetails;

let validator = Validator::new()
    .expect(CustomExpectation::new(
        "email_domain_check",
        "All emails must be from approved domains",
        |data| {
            let email_col = data.column("email")?;
            let emails = email_col.str()?;

            let approved_domains = vec!["example.com", "company.org"];
            let mut invalid_emails = Vec::new();

            for (i, email_opt) in emails.into_iter().enumerate() {
                if let Some(email) = email_opt {
                    let domain = email.split('@').nth(1);
                    if let Some(d) = domain {
                        if !approved_domains.contains(&d) {
                            invalid_emails.push(i);
                        }
                    }
                }
            }

            Ok(ExpectationResult {
                passed: invalid_emails.is_empty(),
                expectation_name: "email_domain_check".to_string(),
                details: ExpectationDetails::Column(
                    /* column details */
                ),
            })
        }
    ));
```

### Reusable Custom Expectations

Create reusable custom expectations:

```rust
use dataval::{ColumnExpectation, Expectation, DataFrame};
use dataval::ExpectationResult;

pub struct EmailDomainExpectation {
    column: String,
    approved_domains: Vec<String>,
}

impl EmailDomainExpectation {
    pub fn new(column: impl Into<String>, approved_domains: Vec<String>) -> Self {
        Self {
            column: column.into(),
            approved_domains,
        }
    }
}

impl Expectation<DataFrame> for EmailDomainExpectation {
    fn validate(&self, data: &DataFrame) -> Result<ExpectationResult, ValidationError> {
        let email_col = data.column(&self.column)?;
        let emails = email_col.str()?;

        let mut invalid_count = 0;
        for email_opt in emails.into_iter() {
            if let Some(email) = email_opt {
                let domain = email.split('@').nth(1);
                if let Some(d) = domain {
                    if !self.approved_domains.contains(&d.to_string()) {
                        invalid_count += 1;
                    }
                }
            }
        }

        Ok(ExpectationResult {
            passed: invalid_count == 0,
            expectation_name: "email_domain_check".to_string(),
            details: ExpectationDetails::Column(
                /* column details */
            ),
        })
    }

    fn description(&self) -> String {
        format!("Emails must be from approved domains: {:?}", self.approved_domains)
    }

    fn name(&self) -> String {
        "email_domain_check".to_string()
    }
}

// Usage
let validator = Validator::new()
    .expect(EmailDomainExpectation::new(
        "email",
        vec!["example.com".to_string(), "company.org".to_string()]
    ));
```

