## Common Patterns

### Pattern 1: Validate Before ML Training

```rust
use dataval::{Validator, expectations::*};

// Validate training data
let validator = Validator::new()
    // Feature validation
    .expect(column::no_nulls("feature_1"))
    .expect(column::in_range("feature_1", 0.0..=1.0))
    .expect(column::no_nulls("feature_2"))

    // Label validation
    .expect(column::in_set("label", [0, 1]))

    // Distribution checks
    .expect(statistical::mean_in_range("feature_1", 0.4..=0.6));

let report = validator.validate(&training_df)?;

if report.quality_score() < 95.0 {
    return Err("Training data quality too low".into());
}
```

### Pattern 2: Data Pipeline Validation

```rust
use dataval::{Validator, expectations::column::*};

fn validate_pipeline_stage(
    stage_name: &str,
    data: &DataFrame,
    expected_rows: usize
) -> Result<(), Error> {
    let report = Validator::new()
        .expect(row::count_equals(expected_rows))
        .expect(no_nulls("id"))
        .validate(data)?;

    if !report.passed() {
        eprintln!("Stage '{}' failed validation:", stage_name);
        eprintln!("{}", report);
        return Err("Pipeline validation failed".into());
    }

    Ok(())
}

// Use in pipeline
validate_pipeline_stage("extract", &extracted_df, 1000)?;
validate_pipeline_stage("transform", &transformed_df, 1000)?;
validate_pipeline_stage("load", &loaded_df, 1000)?;
```

### Pattern 3: Incremental Validation

```rust
use dataval::{Validator, expectations::row::*};

// Track previous row count
let mut previous_count = 0;

// Load new data
let df = load_new_data()?;

// Ensure row count changed within threshold
let validator = Validator::new()
    .expect(row::count_changed(
        previous_count,
        0.1  // Allow 10% change
    ));

let report = validator.validate(&df)?;
previous_count = df.height();
```

### Pattern 4: Multi-Column Validation

```rust
use dataval::{Validator, expectations::column::*};

// Validate related columns
let validator = Validator::new()
    .expect(no_nulls("start_date"))
    .expect(no_nulls("end_date"))
    .expect(CustomExpectation::new(
        "end_after_start",
        "End date must be after start date",
        |data| {
            let starts = data.column("start_date")?;
            let ends = data.column("end_date")?;
            // Validate ends > starts
            Ok(ExpectationResult { /* ... */ })
        }
    ))
    .expect(CustomExpectation::new(
        "duration_positive",
        "Duration must be positive",
        |data| {
            let durations = data.column("duration")?;
            // Validate durations > 0
            Ok(ExpectationResult { /* ... */ })
        }
    ));
```

### Pattern 5: Quality Trend Tracking

```rust
use dataval::{Validator, Profiler};
use std::collections::HashMap;

let mut quality_history: HashMap<DateTime<Utc>, f64> = HashMap::new();

// Validate and track quality
for day in 0..7 {
    let file = format!("data_{}.csv", day);
    let report = Validator::new()
        .expect(column::no_nulls("id"))
        .expect(column::unique("id"))
        .validate_csv(&file)?;

    quality_history.insert(Utc::now(), report.quality_score());
}

// Analyze trend
let scores: Vec<_> = quality_history.values().collect();
let avg_score: f64 = scores.iter().sum::<f64>() / scores.len() as f64;
println!("Average quality over 7 days: {:.1}%", avg_score);
```

