## Writing Custom Expectations

### Basic Custom Expectation

#### Step 1: Define the Expectation Struct

```rust
use dataval::{Expectation, ExpectationResult, ExpectationDetails, ValidationError};
use dataval::Data;

#[derive(Debug, Clone)]
pub struct MyCustomExpectation {
    name: String,
    description: String,
    threshold: f64,
}
```

#### Step 2: Implement Validation Logic

```rust
impl Expectation<DataFrame> for MyCustomExpectation {
    fn validate(&self, data: &DataFrame) -> Result<ExpectationResult, ValidationError> {
        // Extract column
        let column = data.column("my_column")
            .map_err(|e| ValidationError::ColumnNotFound("my_column".to_string()))?;

        // Perform validation
        let values = column.f64()?;
        let result: bool = values
            .into_iter()
            .filter_map(|v| v)
            .all(|v| v < self.threshold);

        // Build result
        Ok(ExpectationResult {
            passed: result,
            expectation_name: self.name(),
            details: ExpectationDetails::Column(ColumnDetails {
                column: "my_column".to_string(),
                null_count: Some(column.null_count()),
                failed_rows: None,  // Optional: specific failed rows
                failed_examples: None,
                message: format!("All values < {}", self.threshold),
            }),
        })
    }

    fn description(&self) -> String {
        self.description.clone()
    }

    fn name(&self) -> String {
        self.name.clone()
    }
}
```

#### Step 3: Use It

```rust
let validator = Validator::new()
    .expect(MyCustomExpectation {
        name: "values_below_threshold".to_string(),
        description: "All values must be below threshold".to_string(),
        threshold: 100.0,
    })
    .validate(&data)?;
```

### Advanced Custom Expectation

#### With Failed Row Tracking

```rust
impl Expectation<DataFrame> for MyCustomExpectation {
    fn validate(&self, data: &DataFrame) -> Result<ExpectationResult, ValidationError> {
        let column = data.column("my_column")?;
        let values = column.f64()?;

        // Track failures
        let mut failed_rows = Vec::new();
        let mut failed_values = Vec::new();

        for (i, value_opt) in values.into_iter().enumerate() {
            if let Some(value) = value_opt {
                if value >= self.threshold {
                    failed_rows.push(i);
                    failed_values.push(Value::Float(value));
                }
            }
        }

        let passed = failed_rows.is_empty();

        Ok(ExpectationResult {
            passed,
            expectation_name: self.name(),
            details: ExpectationDetails::Column(ColumnDetails {
                column: "my_column".to_string(),
                null_count: Some(column.null_count()),
                failed_rows: if failed_rows.len() <= 100 {
                    Some(failed_rows)
                } else {
                    None  // Too many to track
                },
                failed_examples: if failed_values.len() > 10 {
                    Some(failed_values.into_iter().take(10).collect())
                } else {
                    None
                },
                message: if passed {
                    format!("All {} values < {}", values.len(), self.threshold)
                } else {
                    format!("{} values >= {}", failed_rows.len(), self.threshold)
                },
            }),
        })
    }
}
```

