### Expectation Builder Pattern

```rust
pub struct MyCustomExpectationBuilder {
    name: String,
    description: String,
    threshold: Option<f64>,
    allow_nulls: bool,
}

impl MyCustomExpectationBuilder {
    pub fn new(name: impl Into<String>) -> Self {
        Self {
            name: name.into(),
            description: String::new(),
            threshold: None,
            allow_nulls: false,
        }
    }

    pub fn description(mut self, desc: impl Into<String>) -> Self {
        self.description = desc.into();
        self
    }

    pub fn threshold(mut self, value: f64) -> Self {
        self.threshold = Some(value);
        self
    }

    pub fn allow_nulls(mut self, allow: bool) -> Self {
        self.allow_nulls = allow;
        self
    }

    pub fn build(self) -> Result<MyCustomExpectation, BuilderError> {
        Ok(MyCustomExpectation {
            name: self.name,
            description: self.description,
            threshold: self.threshold.ok_or(BuilderError::MissingThreshold)?,
            allow_nulls: self.allow_nulls,
        })
    }
}

// Usage
