impl Expectation<DataFrame> for MyExpectation {
    fn estimated_cost(&self) -> ValidationCost {
        match self {
            MyExpectation::SimpleCheck => ValidationCost::Low,
            MyExpectation::ColumnScan => ValidationCost::Medium,
            MyExpectation::Statistical => ValidationCost::High,
        }
    }
}
