#### Benchmark Validations

```rust
use std::time::Instant;

fn benchmark_expectation<E: Expectation<DataFrame>>(
    expectation: &E,
    data: &DataFrame,
    iterations: usize
) -> Duration {
    let start = Instant::now();

    for _ in 0..iterations {
        let _ = expectation.validate(data);
    }

    start.elapsed() / iterations as u32
}

