### Optimization Strategies

#### 1. Use Columnar Operations

```rust
// Slow: Row iteration
for row in df.iter() {
    if row.get_value("column") > threshold {
        // ...
    }
}

// Fast: Columnar operation
let column = df.column("column")?;
let mask = column.f64()?.apply(|v| v > threshold);
let count = mask.into_iter().filter(|b| *b).count();
```

#### 2. Lazy Evaluation

```rust
// Instead of multiple passes:
let null_count = column.null_count();
let unique_count = column.unique()?.height();
let mean = column.mean()?;

// Use LazyFrame for single pass:
let lf = df.clone().lazy();
let result = lf
    .select([
        col("column").null_count().alias("nulls"),
        col("column").n_unique().alias("unique"),
        col("column").mean().alias("mean"),
    ])
    .collect()?;
```

#### 3. Sampling for Large Datasets

```rust
impl Validator {
    pub fn validate_sampled(&self, data: &DataFrame, sample_size: usize) -> Result<ValidationReport, Error> {
        if data.height() <= sample_size {
            return self.validate(data);
        }

        // Sample rows
        let sample = data.sample_n(sample_size, false, false, None)?;

        // Validate sample
        self.validate(&sample)
    }
}
```

#### 4. Cache Computed Statistics

```rust
pub struct CachedValidator {
    validator: Validator,
    cache: HashMap<String, CachedStats>,
}

pub struct CachedStats {
    computed_at: DateTime<Utc>,
    null_count: usize,
    mean: f64,
    stddev: f64,
}

impl CachedValidator {
    pub fn validate_with_cache(&mut self, data: &DataFrame) -> Result<ValidationReport, Error> {
        // Check cache
        if let Some(cached) = self.cache.get("data_key") {
            if cached.computed_at.elapsed() < Duration::from_secs(60) {
                // Use cached values
                return self.validate_using_stats(data, cached);
            }
        }

        // Compute and cache
        let stats = self.compute_stats(data)?;
        self.cache.insert("data_key".to_string(), stats);
        self.validate_using_stats(data, &stats)
    }
}
```

#### 5. Parallel by Column Group

```rust
impl Validator {
    pub fn validate_parallel_by_column(&self, data: &DataFrame) -> Result<ValidationReport, Error> {
        // Group expectations by column
        let mut by_column: HashMap<String, Vec<Box<dyn Expectation<DataFrame>>>> = HashMap::new();

        for exp in &self.expectations {
            let column = exp.column_name();  // Implement this
            by_column.entry(column).or_default().push(exp.clone());
        }

        // Validate each column in parallel
        let results: Vec<_> = by_column
            .into_par_iter()
            .flat_map(|(column, exps)| {
                let column_data = data.column(&column).unwrap();
                exps.into_iter().map(|exp| exp.validate(data)).collect::<Vec<_>>()
            })
            .collect();

        Ok(ValidationReport::new(results))
    }
}
```

