### Efficient Statistics Computation

```rust
impl Profiler {
    pub fn compute_column_statistics(&self, column: &Series) -> Option<ColumnStatistics> {
        match column.dtype() {
            DataType::Float64 | DataType::Float32 | DataType::Int64 | DataType::Int32 => {
                Some(ColumnStatistics {
                    min: column.min().ok(),
                    max: column.max().ok(),
                    mean: column.mean().ok(),
                    median: column.median().ok(),
                    stddev: column.stddev(0).ok(),
                    variance: column.variance(0).ok(),
                    mode: column.mode().ok().and_then(|v| v.get(0).cloned()),
                    percentiles: self.compute_percentiles(column, &[25, 50, 75, 90, 95, 99]),
                })
            },
            _ => None,
        }
    }

    fn compute_percentiles(&self, column: &Series, percentiles: &[usize]) -> HashMap<usize, f64> {
        percentiles
            .iter()
            .filter_map(|&p| {
                column.quantile(p as f64 / 100.0).ok()
                    .map(|v| (p, v))
            })
            .collect()
    }
}
```

### Pattern Detection

```rust
impl Profiler {
    pub fn detect_patterns(&self, column: &Series) -> ColumnPatterns {
        let strings = column.str();
        let mut patterns = ColumnPatterns::default();

        if let Ok(str_iter) = strings {
            let sample: Vec<_> = str_iter
                .into_iter()
                .filter_map(|s| s)
                .take(1000)
                .collect();

            patterns.email_pattern = sample.iter()
                .filter(|s| is_email_pattern(s))
                .count() as f64 / sample.len() as f64 > 0.9;

            patterns.url_pattern = sample.iter()
                .filter(|s| is_url_pattern(s))
                .count() as f64 / sample.len() as f64 > 0.9;

            patterns.uuid_pattern = sample.iter()
                .filter(|s| is_uuid_pattern(s))
                .count() as f64 / sample.len() as f64 > 0.9;

            patterns.date_pattern = sample.iter()
                .filter(|s| is_date_pattern(s))
                .count() as f64 / sample.len() as f64 > 0.9;
        }

        patterns
    }
}

fn is_email_pattern(s: &str) -> bool {
    regex::Regex::new(r"^[^@]+@[^@]+\.[^@]+$").unwrap().is_match(s)
}

fn is_uuid_pattern(s: &str) -> bool {
    regex::Regex::new(r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$").unwrap().is_match(s)
}
