### Histogram Computation

```rust
impl Profiler {
    pub fn compute_histogram(&self, column: &Series, num_bins: usize) -> Option<Histogram> {
        let numeric = column.f64().ok()?;
        let values: Vec<f64> = numeric.into_iter().filter_map(|v| v).collect();

        if values.is_empty() {
            return None;
        }

        let min = values.iter().cloned().fold(f64::INFINITY, f64::min);
        let max = values.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
        let bin_width = (max - min) / num_bins as f64;

        let mut counts = vec![0usize; num_bins];
        for value in values {
            let bin = ((value - min) / bin_width).floor() as usize;
            let bin = bin.min(num_bins - 1);
            counts[bin] += 1;
        }

        let mut bins = Vec::with_capacity(num_bins + 1);
        for i in 0..=num_bins {
            bins.push(min + (i as f64 * bin_width));
        }

        Some(Histogram { bins, counts })
    }
}
```

### Correlation Computation

```rust
impl Profiler {
    pub fn compute_correlations(&self, df: &DataFrame) -> HashMap<(String, String), f64> {
        let numeric_columns: Vec<_> = df.get_columns()
            .iter()
            .filter(|c| is_numeric(c.dtype()))
            .map(|c| c.name().to_string())
            .collect();

        let mut correlations = HashMap::new();

        for (i, col1) in numeric_columns.iter().enumerate() {
            for col2 in numeric_columns.iter().skip(i + 1) {
                if let Ok(corr) = self.compute_pearson_correlation(df, col1, col2) {
                    correlations.insert((col1.clone(), col2.clone()), corr);
                }
            }
        }

        correlations
    }

    fn compute_pearson_correlation(&self, df: &DataFrame, col1: &str, col2: &str) -> Result<f64, Error> {
        let c1 = df.column(col1)?.f64()?;
        let c2 = df.column(col2)?.f64()?;

        let mean1 = c1.mean().ok_or("No mean")?;
        let mean2 = c2.mean().ok_or("No mean")?;

        let mut numerator = 0.0;
        let mut sum_sq1 = 0.0;
        let mut sum_sq2 = 0.0;

        for (v1_opt, v2_opt) in c1.into_iter().zip(c2.into_iter()) {
            if let (Some(v1), Some(v2)) = (v1_opt, v2_opt) {
                let diff1 = v1 - mean1;
                let diff2 = v2 - mean2;
                numerator += diff1 * diff2;
                sum_sq1 += diff1 * diff1;
                sum_sq2 += diff2 * diff2;
            }
        }

        let denominator = (sum_sq1 * sum_sq2).sqrt();
        if denominator == 0.0 {
            Ok(0.0)
        } else {
            Ok(numerator / denominator)
        }
    }
}
```

