## Anomaly Detection Algorithms

### Z-Score Detector

```rust
pub struct ZScoreDetector {
    threshold: f64,
}

impl AnomalyDetector for ZScoreDetector {
    fn detect(&self, data: &Series) -> Result<Vec<usize>, AnomalyError> {
        let values = data.f64()?;
        let mean = values.mean().ok_or("No mean")?;
        let stddev = values.stddev(0).ok_or("No stddev")?;

        if stddev == 0.0 {
            return Ok(Vec::new());
        }

        Ok(values
            .into_iter()
            .enumerate()
            .filter_map(|(i, v)| {
                v.map(|val| {
                    let z_score = (val - mean) / stddev;
                    if z_score.abs() > self.threshold {
                        Some(i)
                    } else {
                        None
                    }
                })
                .flatten()
            })
            .collect())
    }
}
```

### IQR Detector

```rust
pub struct IQRDetector {
    multiplier: f64,
}

impl AnomalyDetector for IQRDetector {
    fn detect(&self, data: &Series) -> Result<Vec<usize>, AnomalyError> {
        let values = data.f64()?;
        let q1 = data.quantile(0.25).ok_or("No Q1")?;
        let q3 = data.quantile(0.75).ok_or("No Q3")?;
        let iqr = q3 - q1;

        let lower = q1 - (self.multiplier * iqr);
        let upper = q3 + (self.multiplier * iqr);

        Ok(values
            .into_iter()
            .enumerate()
            .filter_map(|(i, v)| {
