### Modified Z-Score Detector

```rust
pub struct ModifiedZScoreDetector {
    threshold: f64,
}

impl AnomalyDetector for ModifiedZScoreDetector {
    fn detect(&self, data: &Series) -> Result<Vec<usize>, AnomalyError> {
        let values = data.f64()?;
        let median = data.median().ok_or("No median")?;

        // Compute MAD (Median Absolute Deviation)
        let deviations: Vec<f64> = values
            .into_iter()
            .filter_map(|v| v)
            .map(|v| (v - median).abs())
            .collect();

        let mad = median_sorted(&deviations);
        if mad == 0.0 {
            return Ok(Vec::new());
        }

        // Modified Z-score = 0.6745 * (x - median) / MAD
        const CONST: f64 = 0.6745;

        Ok(values
            .into_iter()
            .enumerate()
            .filter_map(|(i, v)| {
                v.map(|val| {
                    let modified_z = CONST * (val - median) / mad;
                    if modified_z.abs() > self.threshold {
                        Some(i)
                    } else {
                        None
                    }
                })
                .flatten()
            })
            .collect())
    }
}

fn median_sorted(data: &[f64]) -> f64 {
    let mut sorted = data.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let len = sorted.len();
    if len % 2 == 0 {
        (sorted[len / 2 - 1] + sorted[len / 2]) / 2.0
    } else {
        sorted[len / 2]
    }
}
```

