#[quickcheck_macros::quickcheck]
fn test_unique_always_passes_for_unique_data(ids: Vec<i64>) -> bool {
    if ids.is_empty() {
        return true;
    }

    // Create unique set
    let unique_ids: HashSet<_> = ids.iter().collect();

    if unique_ids.len() != ids.len() {
        return true;  // Skip if not unique
    }

    let df = df!("id" => &ids).unwrap();
    let exp = unique("id");
    let result = exp.validate(&df).unwrap();
    result.passed()
}

#[quickcheck_macros::quickcheck]
fn test_in_range_always_passes_for_valid_data(
    values: Vec<i32>,
    min: i32,
    max: i32
) -> bool {
    if min >= max || values.is_empty() {
        return true;
    }

    // Filter to values in range
    let valid_values: Vec<_> = values.into_iter()
        .filter(|v| v >= &min && v <= &max)
        .collect();

    let df = df!("value" => &valid_values).unwrap();
    let exp = in_range("value", min..=max);
    let result = exp.validate(&df).unwrap();
    result.passed()
}
