### Use Case: Validate Data at Each Pipeline Stage

Ensure data quality at extract, transform, and load stages.

#### Architecture with workflow-rs

```rust
use workflow_rs::{Workflow, Stage, StageError};
use dataval::Validator;

fn create_etl_workflow() -> Workflow<DataFrame> {
    Workflow::new("etl_pipeline")
        .stage("extract", extract_data)
        .stage("validate_extracted", validate_extracted_data)
        .stage("transform", transform_data)
        .stage("validate_transformed", validate_transformed_data)
        .stage("load", load_data)
        .stage("validate_loaded", validate_loaded_data)
}

fn extract_data(_input: ()) -> Result<DataFrame, StageError> {
    // Extract from source
    let df = CsvReader::from_path("source.csv")?
        .finish()?;
    Ok(df)
}

fn validate_extracted_data(data: DataFrame) -> Result<DataFrame, StageError> {
    let validator = Validator::new()
        .expect(no_nulls("id"))
        .expect(unique("id"))
        .expect(row::count_at_least(1));

    let report = validator.validate(&data)?;

    if !report.passed() {
        return Err(StageError::ValidationFailed(
            format!("Extracted data validation failed: {}", report)
        ));
    }

    Ok(data)
}

fn transform_data(data: DataFrame) -> Result<DataFrame, StageError> {
    // Apply transformations
    let transformed = data
        .lazy()
        .select(&[
            col("id"),
            col("value") * lit(2.0),
        ])
        .collect()?;

    Ok(transformed)
}

fn validate_transformed_data(data: DataFrame) -> Result<DataFrame, StageError> {
    let validator = Validator::new()
        .expect(no_nulls("id"))
        .expect(greater_than("value", 0.0))
        .expect(statistical::mean_in_range("value", 10.0..=1000.0));

    let report = validator.validate(&data)?;

    if report.quality_score() < 95.0 {
        return Err(StageError::ValidationFailed(
            format!("Transformed data quality too low: {:.1}%", report.quality_score())
        ));
    }

    Ok(data)
}

