    // Load to warehouse
    // ...
    Ok(())
}

fn validate_loaded_data(_input: ()) -> Result<(), StageError> {
    // Validate data in warehouse
    let adapter = PostgresAdapter::connect("postgresql://localhost/warehouse")?;

    let validator = Validator::new()
        .expect(no_nulls("id"))
