#### Idempotency Validation

Ensure pipeline can be re-run safely:

```rust
struct IdempotencyValidator {
    adapter: PostgresAdapter,
    table: String,
    hash_column: String,
}

impl IdempotencyValidator {
    pub fn validate_no_duplicates(&self) -> Result<(), Error> {
        let query = format!(
            "SELECT {}, COUNT(*) as cnt FROM {} GROUP BY {} HAVING COUNT(*) > 1",
            self.hash_column, self.table, self.hash_column
        );

        let duplicate_count = self.adapter.count(query)?;

        if duplicate_count > 0 {
            return Err(format!(
                "Found {} duplicate rows in table {}",
                duplicate_count, self.table
            ).into());
        }

        Ok(())
    }
}
