## ML Data Validation

### Use Case: Validate ML Training and Production Data

Ensure ML models are trained on high-quality data and production data matches training distribution.

#### Training Data Validation

```rust
use dataval::{Validator, Profiler};

pub struct MLDataValidator {
    feature_expectations: HashMap<String, Vec<ColumnExpectation>>,
    label_expectations: Vec<ColumnExpectation>,
}

impl MLDataValidator {
    pub fn validate_training_data(&self, data: &DataFrame) -> Result<TrainingValidationReport, Error> {
        let mut reports = Vec::new();

        // Validate each feature
        for (feature, expectations) in &self.feature_expectations {
            let validator = Validator::new()
                .expect_all(expectations.clone());

            let report = validator.validate(data)?;
            reports.push((feature.clone(), report));
        }

        // Validate labels
        let label_validator = Validator::new()
            .expect_all(self.label_expectations.clone());

        let label_report = label_validator.validate(data)?;

        Ok(TrainingValidationReport {
            feature_reports: reports,
            label_report,
        })
    }

    pub fn validate_feature_distributions(
        &self,
        training_data: &DataFrame,
        production_data: &DataFrame
    ) -> Result<DistributionDriftReport, Error> {
        let mut drifts = Vec::new();

        for feature in self.feature_expectations.keys() {
            let train_col = training_data.column(feature)?;
            let prod_col = production_data.column(feature)?;

            // Compute KS test
            let ks_statistic = self.kolmogorov_smirnov_test(&train_col, &prod_col)?;

            if ks_statistic.p_value < 0.05 {
                drifts.push(FeatureDrift {
                    feature: feature.clone(),
                    ks_statistic: ks_statistic.statistic,
                    p_value: ks_statistic.p_value,
                    significant: true,
                });
            }
        }

        Ok(DistributionDriftReport { drifts })
    }
}
```

