        // Numeric features
        for (feature, (min, max)) in &self.numeric_ranges {
            validator = validator.expect(in_range(feature, *min..=*max));
        }

        // Categorical features
        for (feature, values) in &self.categorical_values {
            validator = validator.expect(in_set(
                feature,
                values.iter().cloned()
            ));
        }

        let report = validator.validate(data)?;

        Ok(FeatureValidationReport {
            total_features: self.numeric_ranges.len() + self.categorical_values.len(),
            passed_features: report.passed_expectations(),
            failed_features: report.failed_expectations(),
            quality_score: report.quality_score(),
        })
    }
}
