#### Label Validation

```rust
pub fn validate_labels(data: &DataFrame) -> Result<LabelValidationReport, Error> {
    let validator = Validator::new()
        .expect(no_nulls("label"))
        .expect(in_set("label", [0, 1]))  // Binary classification
        .expect(statistical::distribution_matches(
            "label",
            &Distribution::Binary { p: 0.5 }
        ));

    let report = validator.validate(data)?;

    // Check class balance
    let label_col = data.column("label")?;
    let labels = label_col.i32()?;
    let class_counts: HashMap<i32, usize> = labels
        .into_iter()
        .filter_map(|l| l)
        .fold(HashMap::new(), |mut acc, l| {
            *acc.entry(l).or_insert(0) += 1;
            acc
        });

    let class_0_count = *class_counts.get(&0).unwrap_or(&0);
    let class_1_count = *class_counts.get(&1).unwrap_or(&0);
    let imbalance_ratio = class_0_count as f64 / class_1_count as f64;

    Ok(LabelValidationReport {
        passed: report.passed(),
        class_0_count,
        class_1_count,
        imbalance_ratio,
        balanced: imbalance_ratio >= 0.8 && imbalance_ratio <= 1.2,
    })
}
