        let production_profile = Profiler::new().profile(production_data)?;

        let mut drifts = Vec::new();

        for (col_name, train_col) in &training_profile.columns {
            if let Some(prod_col) = production_profile.column(col_name) {
                // Compare means
                if let (Some(train_mean), Some(prod_mean)) = (
                    train_col.statistics.as_ref().and_then(|s| s.mean),
                    prod_col.statistics.as_ref().and_then(|s| s.mean)
                ) {
                    let mean_diff = (train_mean - prod_mean).abs() / train_mean;

                    if mean_diff > self.threshold {
                        drifts.push(DriftInfo {
                            column: col_name.clone(),
                            drift_type: DriftType::MeanShift,
                            training_value: train_mean,
                            production_value: prod_mean,
                            diff_percent: mean_diff * 100.0,
                        });
                    }
                }

                // Compare distributions (KS test)
                let train_data = training_data.column(col_name)?;
                let prod_data = production_data.column(col_name)?;
                let ks_result = self.ks_test(&train_data, &prod_data)?;

                if ks_result.p_value < 0.05 {
                    drifts.push(DriftInfo {
                        column: col_name.clone(),
                        drift_type: DriftType::DistributionChange,
                        training_value: ks_result.statistic,
                        production_value: ks_result.p_value,
                        diff_percent: ks_result.statistic * 100.0,
                    });
                }
            }
        }

        Ok(DriftReport {
            has_drift: !drifts.is_empty(),
            drifts,
        })
    }
}
