impl MigrationValidator {
    pub fn validate_row_counts(&self, tables: Vec<String>) -> Result<RowValidationReport, Error> {
        let mut results = Vec::new();

        for table in &tables {
            let source_count = self.source_adapter.row_count(table)?;
            let target_count = self.target_adapter.row_count(table)?;

            let match = source_count == target_count;

            results.push(TableRowValidation {
                table: table.clone(),
                source_count,
                target_count,
                match,
                difference: (source_count as i64 - target_count as i64).abs(),
            });
        }

        Ok(RowValidationReport { results })
    }
