#### Schema Validation

```rust
impl MigrationValidator {
    pub fn validate_schema_match(&self, table: &str) -> Result<SchemaValidationReport, Error> {
        let source_schema = self.source_adapter.get_schema(table)?;
        let target_schema = self.target_adapter.get_schema(table)?;

        let mut mismatches = Vec::new();

        for source_col in &source_schema.columns {
            if let Some(target_col) = target_schema.columns.iter()
                .find(|c| c.name == source_col.name)
            {
                if source_col.dtype != target_col.dtype {
                    mismatches.push(SchemaMismatch {
                        column: source_col.name.clone(),
                        source_type: source_col.dtype.clone(),
                        target_type: target_col.dtype.clone(),
                    });
                }
            } else {
                mismatches.push(SchemaMismatch {
                    column: source_col.name.clone(),
                    source_type: source_col.dtype.clone(),
                    target_type: "MISSING".to_string(),
                });
            }
        }

        Ok(SchemaValidationReport {
            table: table.to_string(),
            match: mismatches.is_empty(),
            mismatches,
        })
    }
}
