## Integration with workflow-rs

### Complete Pipeline Integration

```rust
use workflow_rs::{Workflow, Stage};
use dataval::Validator;

pub fn create_validated_workflow() -> Workflow<DataFrame> {
    Workflow::new("data_pipeline")
        .stage("extract", extract)
        .stage("validate_raw", validate_raw_data)
        .stage("clean", clean_data)
        .stage("validate_cleaned", validate_cleaned_data)
        .stage("transform", transform_data)
        .stage("validate_transformed", validate_transformed_data)
        .stage("enrich", enrich_data)
        .stage("validate_final", validate_final_data)
        .stage("load", load_data)
}

fn validate_raw_data(data: DataFrame) -> Result<DataFrame, StageError> {
    let validator = Validator::new()
        .expect(no_nulls("id"))
        .expect(unique("id"))
        .expect(row::count_at_least(1));

    let report = validator.validate(&data)?;

    if !report.passed() {
        metrics::counter!("validation.failures", 1, "stage" => "raw");
        return Err(StageError::ValidationFailed(
            format!("Raw data validation failed")
        ));
    }

    metrics::gauge!("validation.quality_score", report.quality_score(), "stage" => "raw");
    Ok(data)
}

fn validate_cleaned_data(data: DataFrame) -> Result<DataFrame, StageError> {
    let validator = Validator::new()
        .expect(no_nulls("id"))
        .expect(nulls_below_percent("email", 0.01))  // Allow 1% nulls
        .expect(is_email("email"));

    let report = validator.validate(&data)?;

    if report.quality_score() < 95.0 {
        return Err(StageError::ValidationFailed(
            format!("Cleaned data quality {:.1}% < 95%", report.quality_score())
        ));
    }

    Ok(data)
}

fn validate_transformed_data(data: DataFrame) -> Result<DataFrame, StageError> {
    let validator = Validator::new()
        .expect(greater_than("calculated_value", 0.0))
        .expect(less_than("calculated_value", 1000000.0));

    let report = validator.validate(&data)?;

    if !report.passed() {
        return Err(StageError::ValidationFailed(
            "Transformed data out of range".to_string()
        ));
    }

    Ok(data)
}

fn validate_final_data(data: DataFrame) -> Result<DataFrame, StageError> {
    let validator = Validator::new()
        .expect_all([
            no_nulls("id"),
            unique("id"),
            no_nulls("name"),
            no_nulls("email"),
            is_email("email"),
            no_nulls("created_at"),
            is_date("created_at", Some("%Y-%m-%d %H:%M:%S")),
        ]);

    let report = validator.validate(&data)?;

    if report.quality_score() < 100.0 {
        metrics::counter!("validation.failures", 1, "stage" => "final");
        return Err(StageError::ValidationFailed(
            format!("Final data quality {:.1}% < 100%", report.quality_score())
        ));
    }

    metrics::gauge!("validation.quality_score", report.quality_score(), "stage" => "final");
    Ok(data)
}
```

