```rust
use metrics::{gauge, histogram, counter};

pub fn track_validation_metrics(report: &ValidationReport, dataset: &str) {
    // Quality score
    gauge!("data_quality_score", report.quality_score(), "dataset" => dataset);

    // Expectation counts
    gauge!("expectations.total", report.expectations.len() as f64, "dataset" => dataset);
    gauge!("expectations.passed", report.passed_expectations() as f64, "dataset" => dataset);
    gauge!("expectations.failed", report.failed_expectations() as f64, "dataset" => dataset);

    // Validation duration
    histogram!("validation.duration_ms", report.duration.as_millis() as f64, "dataset" => dataset);

    // Row/column counts
    gauge!("data.row_count", report.row_count as f64, "dataset" => dataset);
    gauge!("data.column_count", report.column_count as f64, "dataset" => dataset);

    // Track failures
    if !report.passed() {
        counter!("validation.failures", 1, "dataset" => dataset);
    }
}

pub fn track_profiling_metrics(profile: &DataProfile, dataset: &str) {
    for (col_name, col_profile) in &profile.columns {
        // Null percentages
        gauge!(
            "column.null_percentage",
            col_profile.null_percentage,
            "dataset" => dataset,
            "column" => col_name
        );

        // Unique percentages
        gauge!(
            "column.unique_percentage",
            col_profile.unique_percentage,
            "dataset" => dataset,
            "column" => col_name
        );

        // Statistics
        if let Some(stats) = &col_profile.statistics {
            if let Some(mean) = stats.mean {
                gauge!("column.mean", mean, "dataset" => dataset, "column" => col_name);
            }
            if let Some(stddev) = stats.stddev {
                gauge!("column.stddev", stddev, "dataset" => dataset, "column" => col_name);
            }
        }
    }
}
