### Code

```rust
use dataval::{Validator, CustomExpectation, ExpectationResult, ExpectationDetails, ValidationError};
use dataval::Data;
use polars::prelude::*;

// Custom validator: Sum of credits must equal sum of debits
fn validate_accounting_balance() -> CustomExpectation {
    CustomExpectation::new(
        "accounting_balance",
        "Sum of credits must equal sum of debits",
        |data: &DataFrame| {
            // Get credit and debit columns
            let credits = data.column("credit")?.f64()?;
            let debits = data.column("debit")?.f64()?;

            // Calculate sums
            let credit_sum: f64 = credits.into_iter().filter_map(|v| v).sum();
            let debit_sum: f64 = debits.into_iter().filter_map(|v| v).sum();

            let difference = (credit_sum - debit_sum).abs();
            let passed = difference < 0.01;  // Allow small rounding errors

            Ok(ExpectationResult {
                passed,
                expectation_name: "accounting_balance".to_string(),
                details: ExpectationDetails::Column(
                    dataval::ColumnDetails {
                        column: "accounting".to_string(),
                        null_count: None,
                        failed_rows: None,
                        failed_examples: None,
                        message: format!(
                            "Credit sum: ${:.2}, Debit sum: ${:.2}, Difference: ${:.2}",
                            credit_sum, debit_sum, difference
                        ),
                    }
                ),
            })
        }
    )
}

// Custom validator: All emails must be from approved domains
fn validate_email_domains() -> CustomExpectation {
    CustomExpectation::new(
        "approved_email_domains",
        "All emails must be from approved domains",
        |data: &DataFrame| {
            let email_col = data.column("email")?.str()?;
            let approved_domains = vec!["company.com", "partner.org", "vendor.net"];

            let mut invalid_count = 0;
            let mut invalid_emails = Vec::new();

            for email_opt in email_col.into_iter() {
                if let Some(email) = email_opt {
                    let domain = email.split('@').nth(1);
                    if let Some(d) = domain {
                        if !approved_domains.contains(&d) {
                            invalid_count += 1;
                            if invalid_emails.len() < 5 {
                                invalid_emails.push(email.to_string());
                            }
                        }
                    }
                }
            }

            Ok(ExpectationResult {
                passed: invalid_count == 0,
                expectation_name: "approved_email_domains".to_string(),
                details: ExpectationDetails::Column(
                    dataval::ColumnDetails {
                        column: "email".to_string(),
                        null_count: None,
                        failed_rows: None,
                        failed_examples: if !invalid_emails.is_empty() {
                            Some(
                                invalid_emails
                                    .into_iter()
                                    .map(|e| Value::String(e))
                                    .collect()
                            )
                        } else {
                            None
                        },
                        message: if invalid_count == 0 {
                            "All emails from approved domains".to_string()
                        } else {
                            format!("{} emails from unapproved domains", invalid_count)
                        },
                    }
                ),
            })
        }
    )
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Accounting data
    let accounting_df = df!(
        "transaction_id" => &[1, 2, 3, 4, 5],
        "credit" => &[100.0, 250.0, 75.0, 300.0, 125.0],
        "debit" => &[50.0, 150.0, 75.0, 300.0, 125.0]
    )?;

    // Employee data with emails
    let employee_df = df!(
        "employee_id" => &[1, 2, 3, 4, 5],
        "name" => &["Alice", "Bob", "Charlie", "Diana", "Eve"],
        "email" => &[
            "alice@company.com",
            "bob@partner.org",
            "charlie@vendor.net",
            "diana@external.com",  // Invalid domain
            "eve@company.com"
        ]
    )?;

    // Validate accounting data
    println!("Validating Accounting Data:");
    println!("═════════════════════════════════════════\n");

    let accounting_report = Validator::new()
        .expect(validate_accounting_balance())
        .validate(&accounting_df)?;

    println!("{}", accounting_report);

    // Validate employee data
    println!("\nValidating Employee Data:");
    println!("═════════════════════════════════════════\n");

    let employee_report = Validator::new()
        .expect(validate_email_domains())
        .validate(&employee_df)?;

    println!("{}", employee_report);

    Ok(())
}
