## Example 5: Data Profiling

**Goal**: Automatically analyze data and suggest expectations.

### Code

```rust
use dataval::Profiler;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let profiler = Profiler::new()
        .statistics(true)
        .histograms(true)
        .correlations(true);

    // Profile CSV file
    println!("Profiling users.csv");
    println!("════════════════════════\n");

    let profile = profiler.profile_csv("users.csv")?;

    // Print overview
    println!("Data Overview:");
    println!("  Rows: {}", profile.row_count);
    println!("  Columns: {}", profile.column_count);
    println!("  Profiled at: {}\n", profile.timestamp);

    // Print column details
    println!("Column Details:");
    println!("─────────────────────────────────────────────────────────────\n");

    for (col_name, col_profile) in &profile.columns {
        println!("{} ({})", col_name, col_profile.data_type);

        if col_profile.null_count > 0 {
            println!("  Nulls: {} ({:.2}%)", col_profile.null_count, col_profile.null_percentage);
        } else {
            println!("  Nulls: 0 (clean!)");
        }

        println!("  Unique: {} ({:.2}%)", col_profile.unique_count, col_profile.unique_percentage);

        if let Some(stats) = &col_profile.statistics {
            println!("  Statistics:");
            if let Some(min) = stats.min {
                println!("    Min: {}", min);
            }
            if let Some(max) = stats.max {
                println!("    Max: {}", max);
            }
            if let Some(mean) = stats.mean {
                println!("    Mean: {:.2}", mean);
            }
            if let Some(median) = stats.median {
                println!("    Median: {:.2}", median);
            }
            if let Some(stddev) = stats.stddev {
                println!("    StdDev: {:.2}", stddev);
            }
        }

        if let Some(patterns) = &col_profile.patterns {
            if patterns.email_pattern {
                println!("  Pattern: Email (detected)");
            }
            if patterns.url_pattern {
                println!("  Pattern: URL (detected)");
            }
            if patterns.uuid_pattern {
                println!("  Pattern: UUID (detected)");
            }
        }

        println!();
    }

    // Print correlations
    if !profile.correlations.is_empty() {
        println!("Correlations:");
        println!("─────────────────────────────────────────────────────────────\n");

        for ((col1, col2), corr) in &profile.correlations {
            println!("  {} <-> {}: {:.3}", col1, col2, corr);
        }
        println!();
    }

    // Generate suggestions
    println!("Suggested Expectations:");
    println!("─────────────────────────────────────────────────────────────\n");

    let suggestions = profiler.suggest_expectations_csv("users.csv")?;

    for suggestion in suggestions.iter().filter(|s| s.confidence >= 0.8) {
        println!("{:.0}% - {}", suggestion.confidence * 100.0, suggestion.code_snippet);
        println!("       Reason: {}", suggestion.reason);
        println!();
    }

    Ok(())
}
```

