## Example 6: Alert on Data Quality Issues

**Goal**: Set up alerts when validation fails.

### Code

```rust
use dataval::{Validator, Config};
use dataval::alert::{SlackAlert, EmailAlert, CompositeAlert};
use dataval::expectations::column::*;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Create composite alert
    let alert = CompositeAlert::new()
        .add(Box::new(
            SlackAlert::new("#data-quality")
                .webhook_url(std::env::var("SLACK_WEBHOOK_URL")?)
                .on_quality_score_below(95.0)
        ))
        .add(Box::new(
            EmailAlert::new(vec!["data-team@example.com"])
                .subject("⚠️ Data Quality Alert")
        ));

    // Validate with alerts
    let report = Validator::new()
        .expect(no_nulls("id"))
        .expect(unique("id"))
        .expect(no_nulls("email"))
        .expect(is_email("email"))
        .expect(in_range("age", 0..=120))
        .on_failure(alert)
        .validate_csv("users.csv")?;

    println!("{}", report);

    // Programmatic handling
    if !report.passed() {
        eprintln!("\n⚠️  Validation failed!");
        eprintln!("Quality Score: {:.1}%", report.quality_score());

        // Print failures
        for failure in report.failures() {
            eprintln!("  ✗ {}", failure.expectation_name);
        }

        std::process::exit(1);
    }

    Ok(())
}
```

