### Error Handling

**Define Error Type:**
```rust
use thiserror::Error;

#[derive(Error, Debug)]
pub enum Error {
    #[error("Document not found")]
    NotFound,

    #[error("Duplicate key error")]
    DuplicateKey,

    #[error("Invalid query: {0}")]
    InvalidQuery(String),

    #[error("Index error: {0}")]
    IndexError(String),

    #[error("Storage error: {0}")]
    StorageError(#[from] BackendError),

    #[error("Serialization error: {0}")]
    SerializationError(#[from] bson::ser::Error),

    #[error("IO error: {0}")]
    IoError(#[from] std::io::Error),
}

pub type Result<T> = std::result::Result<T, Error>;
```

### Database Implementation

**src/database.rs:**
```rust
use crate::backend::StorageBackend;
use crate::collection::Collection;
use std::sync::Arc;

#[derive(Clone)]
pub struct Database {
    backend: Arc<dyn StorageBackend>,
}

impl Database {
    pub fn open(path: &str) -> Result<Self> {
        let backend = crate::backend::SqliteBackend::new(path)?;
        Ok(Self {
            backend: Arc::new(backend),
        })
    }

    pub fn collection(&self, name: &str) -> Collection {
        Collection::new(name, self.backend.clone())
    }

    pub fn list_collections(&self) -> Result<Vec<String>> {
        self.backend.list_collections()
    }

    pub fn drop_collection(&self, name: &str) -> Result<()> {
        self.backend.drop_collection(name)
    }
}
```

### Collection Implementation

**src/collection.rs:**
```rust
use crate::backend::StorageBackend;
use crate::query::Query;
use crate::index::IndexManager;
use bson::Document;
use std::sync::Arc;

pub struct Collection {
    name: String,
    backend: Arc<dyn StorageBackend>,
    index_manager: Arc<IndexManager>,
}

impl Collection {
    pub fn new(name: &str, backend: Arc<dyn StorageBackend>) -> Self {
        let index_manager = Arc::new(IndexManager::new(backend.clone()));
        Self {
            name: name.to_string(),
            backend,
            index_manager,
        }
    }

    pub async fn insert_one(&self, doc: impl IntoDocument) -> Result<ObjectId> {
        let doc = doc.into_document()?;

        // Ensure _id exists
        let id = doc.get_object_id("_id)?
            .copied()
            .unwrap_or_else(ObjectId::new);

        let mut doc = doc;
        doc.insert("_id", id);

        // Store
        self.backend.insert(&self.name, &doc)?;

        // Index
        self.index_manager.index_document(&self.name, id, &doc)?;

        Ok(id)
    }

    pub async fn find(&self, query: impl IntoQuery) -> Result<Vec<Document>> {
        let query = query.into_query()?;

        // Use index if available
        if let Some(index) = self.index_manager.find_best_index(&query) {
            self.find_with_index(&query, index).await
        } else {
            self.find_with_scan(&query).await
        }
    }

    // ... more methods
}
```

