        let user = users.find_one(doc!{"name": "Alice"}).await.unwrap();

        assert!(user.is_some());
        assert_eq!(user.unwrap().get_str("name").unwrap(), "Alice");
    }
}
```

### Integration Tests

**tests/test_crud.rs:**
```rust
use docstore::Database;
use bson::doc;

#[tokio::test]
async fn test_full_crud_workflow() {
    // Setup
    let db = Database::open("test_crud").unwrap();
    let users = db.collection("users");

    // Create
    let id = users.insert_one(doc!{
        "name": "Alice",
        "email": "alice@example.com"
    }).await.unwrap();

    // Read
    let user = users.find_one_by_id(id).await.unwrap();
    assert!(user.is_some());

    // Update
    users.update_one(
        doc!{"_id": id},
        doc!{"$set": {"name": "Alice Updated"}}
    ).await.unwrap();

    let updated = users.find_one_by_id(id).await.unwrap();
    assert_eq!(updated.unwrap().get_str("name").unwrap(), "Alice Updated");

    // Delete
    users.delete_one(doc!{"_id": id}).await.unwrap();

    let deleted = users.find_one_by_id(id).await.unwrap();
    assert!(deleted.is_none());

    // Cleanup
    db.drop_collection("users").unwrap();
}
```

