    let users = db.collection("users");
    users.insert_one(doc!{
        "_id": "user1",
        "name": "Alice"
    }).await.unwrap();

    // Run aggregation with lookup
    let results = users.aggregate(vec![
        lookup_stage!({
            "from": "orders",
            "local_field": "_id",
            "foreign_field": "user_id",
            "as": "orders"
        })
    ]).await.unwrap();

    assert_eq!(results.len(), 1);
    assert!(results[0].get_array("orders").unwrap().len() > 0);
}
```

### Step 5: Document Stage

**docs/aggregation.md:**
```markdown
## $lookup Stage

Performs a left outer join to another collection.

### Syntax

```rust
lookup_stage!({
    "from": "foreign_collection",
    "local_field": "local_field_name",
    "foreign_field": "foreign_field_name",
    "as": "output_array_field"
})
```

### Example

```rust
let results = users.aggregate(vec![
    lookup_stage!({
        "from": "orders",
        "local_field": "_id",
        "foreign_field": "user_id",
        "as": "user_orders"
    })
]).await?;
```
```

---

## Debugging

### Logging

**Enable Logging:**
```rust
use log::debug;

#[tokio::main]
async fn main() {
    env_logger::init();

    let db = Database::open("mydb").unwrap();

    debug!("Database opened");

