## Extension Points

### 1. Custom Partitioner

Implement custom partitioning logic:

```rust
use eventstream::Partitioner;

pub struct CustomPartitioner {
    // Your fields
}

impl<K> Partitioner<K> for CustomPartitioner
where
    K: Hash,
{
    fn partition(&self, key: &Option<K>, num_partitions: u32) -> u32 {
        // Your partitioning logic
        match key {
            Some(k) => {
                // Custom hash
                let hash = custom_hash(k);
                hash % num_partitions
            }
            None => 0,
        }
    }
}

// Use it
let producer = Producer::builder()
    .partitioner(CustomPartitioner { /* ... */ })
    .build()?;
```

### 2. Custom Serializer

Implement your own serialization:

```rust
use eventstream::CustomSerializer;

pub struct MySerializer;

impl CustomSerializer for MySerializer {
    fn serialize<T: Serialize>(&self, value: &T) -> Result<Vec<u8>> {
        // Your serialization logic
        let bytes = my_serialize(value)?;
        Ok(bytes)
    }

    fn deserialize<'de, T: Deserialize<'de>>(&self, bytes: &'de [u8]) -> Result<T> {
        // Your deserialization logic
        let value = my_deserialize(bytes)?;
        Ok(value)
    }
}

// Use it
let producer = Producer::builder()
    .key_serializer(Serializer::Custom(Box::new(MySerializer)))
    .build()?;
```

### 3. Custom Storage Backend

Implement a new storage backend:

```rust
use eventstream::storage::Storage;

pub struct MyStorageBackend {
    // Your fields
}

#[async_trait]
impl Storage for MyStorageBackend {
    async fn write_record(
        &self,
        topic: &str,
        partition: u32,
        record: &Record,
    ) -> Result<Offset> {
        // Your write logic
        Ok(Offset(0))
    }

    async fn read_records(
        &self,
        topic: &str,
        partition: u32,
        offset: Offset,
        limit: u32,
    ) -> Result<Vec<Record>> {
        // Your read logic
        Ok(vec![])
    }

    async fn create_topic(
        &self,
        name: &str,
        config: &TopicConfig,
    ) -> Result<()> {
        // Your topic creation logic
        Ok(())
    }

    async fn delete_topic(&self, name: &str) -> Result<()> {
        // Your topic deletion logic
        Ok(())
    }
}
```

### 4. Custom Compression

Add a compression codec:

```rust
use eventstream::compression::Compressor;

pub struct MyCompressor {
    level: u32,
}

impl Compressor for MyCompressor {
    fn compress(&self, data: &[u8]) -> Result<Vec<u8>> {
        // Your compression logic
        Ok(compressed_data)
    }

    fn decompress(&self, data: &[u8]) -> Result<Vec<u8>> {
        // Your decompression logic
        Ok(decompressed_data)
    }

    fn compression_ratio(&self) -> f64 {
        // Report typical compression ratio
        0.5
    }
}

// Register it
Compression::register_custom("my", Box::new(MyCompressor { level: 3 }));
```

### 5. Custom Offset Storage

Implement offset storage:

