## Common Patterns

### Pattern 1: Session Storage

**Store user sessions with auto-expiration:**

```rust
use flashcache::{Cache, SetOptions};
use std::time::Duration;
use serde::{Serialize, Deserialize};

#[derive(Serialize, Deserialize)]
struct Session {
    user_id: u64,
    username: String,
    created_at: DateTime<Utc>,
}

impl Session {
    fn new(user_id: u64, username: String) -> Self {
        Self {
            user_id,
            username,
            created_at: Utc::now(),
        }
    }

    fn key(&self) -> String {
        format!("session:{}", self.user_id)
    }
}

// Create session
async fn create_session(cache: &Cache, user_id: u64, username: String) -> Result<()> {
    let session = Session::new(user_id, username);

    cache.set_with_options(session.key(), &session, SetOptions {
        ttl: Some(Duration::from_secs(1800)), // 30 minutes
        ..Default::default()
    }).await?;

    Ok(())
}

// Get session
async fn get_session(cache: &Cache, user_id: u64) -> Result<Option<Session>> {
    let key = format!("session:{}", user_id);
    cache.get(&key).await
}

// Extend session (sliding expiration)
async fn extend_session(cache: &Cache, user_id: u64) -> Result<()> {
    let key = format!("session:{}", user_id);
    cache.expire(&key, Duration::from_secs(1800)).await?;
    Ok(())
}
```

### Pattern 2: Rate Limiting

**Token bucket algorithm for API rate limiting:**

```rust
use flashcache::Cache;
use std::time::Duration;

struct RateLimiter {
    cache: Cache,
    max_requests: u64,
    window: Duration,
}

impl RateLimiter {
    async fn check_rate_limit(&self, user_id: u64) -> Result<bool> {
        let key = format!("ratelimit:{}", user_id);

        // Get current count
        let count: Option<u64> = self.cache.get(&key).await?;

        match count {
            None => {
                // First request in window
                self.cache.set_with_options(&key, &1, SetOptions {
                    ttl: Some(self.window),
                    ..Default::default()
                }).await?;
                Ok(true)
            }
            Some(n) if n < self.max_requests => {
                // Increment count
                self.cache.incr(&key).await?;
                Ok(true)
            }
            Some(_) => {
                // Rate limit exceeded
                Ok(false)
            }
        }
    }
}

// Usage
let limiter = RateLimiter {
    cache: cache.clone(),
    max_requests: 100,  // 100 requests
    window: Duration::from_secs(60), // per 60 seconds
};

if limiter.check_rate_limit(123).await? {
    // Process request
} else {
    // Return 429 Too Many Requests
}
```

### Pattern 3: Database Query Cache

**Cache expensive database queries:**

```rust
use flashcache::{Cache, SetOptions};
use std::time::Duration;

async fn get_user_posts(cache: &Cache, db: &Db, user_id: u64) -> Result<Vec<Post>> {
    let cache_key = format!("posts:user:{}:recent", user_id);

    // Try cache first
    if let Some(posts) = cache.get(&cache_key).await? {
        println!("Cache hit!");
        return Ok(posts);
    }

    // Cache miss - fetch from database
    println!("Cache miss - fetching from DB");
    let posts = db.fetch_recent_posts(user_id).await?;

    // Store in cache for 5 minutes
    cache.set_with_options(&cache_key, &posts, SetOptions {
        ttl: Some(Duration::from_secs(300)),
        ..Default::default()
    }).await?;

    Ok(posts)
}

// Invalidate cache when user creates new post
async fn invalidate_posts_cache(cache: &Cache, user_id: u64) -> Result<()> {
    let cache_key = format!("posts:user:{}:recent", user_id);
    cache.delete(&cache_key).await?;
    Ok(())
}
```

### Pattern 4: Pub/Sub Messaging

**Real-time notifications:**

```rust
use flashcache::Cache;
use serde::{Serialize, Deserialize};

#[derive(Serialize, Deserialize)]
struct Event {
    event_type: String,
    user_id: u64,
    data: serde_json::Value,
}

// Publisher
async fn publish_user_event(cache: &Cache, event: Event) -> Result<()> {
    let channel = format!("events:user:{}", event.user_id);
    let subscribers = cache.publish(&channel, &event).await?;

    println!("Event published to {} subscribers", subscribers);
    Ok(())
}

// Subscriber
async fn subscribe_to_user_events(cache: &Cache, user_id: u64) -> Result<()> {
    let channel = format!("events:user:{}", user_id);

    let _handle = cache.subscribe(&channel, |event: Event| {
        async move {
            match event.event_type.as_str() {
                "login" => println!("User {} logged in", event.user_id),
                "logout" => println!("User {} logged out", event.user_id),
                "message" => println!("New message: {:?}", event.data),
                _ => println!("Unknown event: {}", event.event_type),
            }
        }.boxed()
    }).await?;

    // Keep task alive
    tokio::time::sleep(Duration::from_secs(3600)).await;

    Ok(())
}
```

### Pattern 5: Leaderboard

**Sorted set for game rankings:**

```rust
use flashcache::Cache;

// Add score
async fn update_score(cache: &Cache, leaderboard: &str, player: &str, score: f64) -> Result<()> {
    cache.zadd(leaderboard, score, player).await?;
    Ok(())
}

// Get top 10
async fn get_top_players(cache: &Cache, leaderboard: &str) -> Result<Vec<(String, f64)>> {
    let top10 = cache.zrevrange(leaderboard, 0, 9, true).await?;
    Ok(top10.into_iter().map(|(p, s)| (p, s.unwrap())).collect())
}

// Get player rank
async fn get_player_rank(cache: &Cache, leaderboard: &str, player: &str) -> Result<Option<usize>> {
    cache.zrevrank(leaderboard, player).await
}

// Increment score
async fn increment_score(cache: &Cache, leaderboard: &str, player: &str, delta: f64) -> Result<()> {
    cache.zincrby(leaderboard, delta, player).await?;
    Ok(())
}

// Usage
update_score(&cache, "game:leaderboard", "player1", 1000.0).await?;
update_score(&cache, "game:leaderboard", "player2", 1500.0).await?;

let top10 = get_top_players(&cache, "game:leaderboard").await?;
for (i, (player, score)) in top10.iter().enumerate() {
    println!("{}: {} - {}", i + 1, player, score);
}
```

