## Building Custom Operators

### Example: Custom Map Operator

Let's build a custom operator that transforms events to uppercase:

```rust
// my_operators.rs

use flow::operator::{Operator, Result};
use flow::event::Event;

pub struct ToUppercase;

impl Operator for ToUppercase {
    type Input = String;
    type Output = String;

    fn process(&mut self, event: String) -> Result<Vec<String>> {
        Ok(vec![event.to_uppercase()])
    }
}
```

**Use it:**

```rust
use flow::StreamProcessor;
use my_operators::ToUppercase;

StreamProcessor::new()
    .source(Kafka::topic("events"))
    .custom(ToUppercase)
    .sink(Stdout::new())
    .build()?
    .run()
    .await?;
```

### Example: Stateful Operator

Build a running average operator:

```rust
// my_operators.rs

use flow::operator::{Operator, Result};
use flow::state::{KeyedState, ValueState};
use std::collections::HashMap;

pub struct RunningAverage {
    state: HashMap<String, (f64, usize)>,  // (sum, count)
}

impl RunningAverage {
    pub fn new() -> Self {
        Self {
            state: HashMap::new(),
        }
    }
}

impl Operator for RunningAverage {
    type Input = (String, f64);  // (key, value)
    type Output = (String, f64);  // (key, average)

    fn process(&mut self, event: (String, f64)) -> Result<Vec<(String, f64)>> {
        let (key, value) = event;

        // Get current state
        let (sum, count) = self.state.entry(key.clone()).or_insert((0.0, 0));

        // Update state
        *sum += value;
        *count += 1;

        // Calculate average
        let avg = *sum / *count as f64;

        Ok(vec![(key, avg)])
    }
}
```

### Example: Custom Aggregate

Build a median aggregate:

```rust
// my_aggregates.rs

use flow::aggregate::Aggregate;
use std::collections::BinaryHeap;

pub struct Median;

impl Aggregate for Median {
    type Input = f64;
    type Output = f64;
    type Accumulator = BinaryHeap<f64>;

    fn initial(&self) -> Self::Accumulator {
        BinaryHeap::new()
    }

    fn add(&self, acc: &mut Self::Accumulator, value: Self::Input) {
        acc.push(value);
    }

    fn merge(&self, acc1: &mut Self::Accumulator, acc2: Self::Accumulator) {
        for value in acc2 {
            acc1.push(value);
        }
    }

    fn finish(&self, acc: Self::Accumulator) -> Self::Output {
        let mut sorted: Vec<_> = acc.into_iter().collect();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
        let len = sorted.len();
        if len % 2 == 0 {
            (sorted[len / 2 - 1] + sorted[len / 2]) / 2.0
        } else {
            sorted[len / 2]
        }
    }
}
```

**Use it:**

```rust
use flow::{StreamProcessor, Window};
use my_aggregates::Median;
use std::time::Duration;

StreamProcessor::new()
    .source(Kafka::topic("metrics"))
    .window(Window::tumbling(Duration::from_secs(60)))
    .aggregate(Median)
    .sink(Stdout::new())
    .build()?
    .run()
    .await?;
```

