## Testing Stream Processors

### Unit Testing Operators

Test your custom operators:

```rust
#[cfg(test)]
mod tests {
    use super::*;
    use flow::sources::VecSource;
    use flow::sinks::VecSink;

    #[tokio::test]
    async fn test_to_uppercase() {
        let input = vec![
            "hello".to_string(),
            "world".to_string(),
        ];
        let mut output = Vec::new();

        StreamProcessor::new()
            .source(VecSource::new(input))
            .custom(ToUppercase)
            .sink(VecSink::new(&mut output))
            .build()?
            .run()
            .await?;

        assert_eq!(output, vec!["HELLO".to_string(), "WORLD".to_string()]);
    }

    #[tokio::test]
    async fn test_running_average() {
        let input = vec![
            ("a".to_string(), 10.0),
            ("a".to_string(), 20.0),
            ("a".to_string(), 30.0),
        ];
        let mut output = Vec::new();

        StreamProcessor::new()
            .source(VecSource::new(input))
            .custom(RunningAverage::new())
            .sink(VecSink::new(&mut output))
            .build()?
            .run()
            .await?;

        assert_eq!(output[0].1, 10.0);  // First event: 10/1 = 10
        assert_eq!(output[1].1, 15.0);  // Second event: (10+20)/2 = 15
        assert_eq!(output[2].1, 20.0);  // Third event: (10+20+30)/3 = 20
    }
}
