### Integration Testing

Test end-to-end pipelines:

```rust
#[tokio::test]
async fn test_windowed_aggregation() {
    let input = vec![
        Event { timestamp: 0, value: 10 },
        Event { timestamp: 30, value: 20 },
        Event { timestamp: 61, value: 30 },  // New window
    ];

    let mut output = Vec::new();

    StreamProcessor::new()
        .source(VecSource::new(input))
        .timestamp_extractor(|event| event.timestamp)
        .window(Window::tumbling(Duration::from_secs(60)))
        .aggregate(Aggregate::sum(|event| event.value))
        .sink(VecSink::new(&mut output))
        .build()?
        .run()
        .await?;

    assert_eq!(output.len(), 2);
    assert_eq!(output[0], 30.0);  // First window: 10 + 20
    assert_eq!(output[1], 30.0);  // Second window: 30
}
```

