impl GatewayQueryPlanner {
    pub fn plan(&self, query: &str) -> Result<ExecutionPlan> {
        let parsed = self.parse(query)?;

        // Analyze which fields belong to which services
        let service_queries = self.split_by_service(&parsed)?;

        // Build execution plan
        Ok(ExecutionPlan {
            queries: service_queries,
            dependencies: self.build_dependencies(&service_queries),
        })
    }

