## CLDR Data Integration

### CLDR Data Structure

CLDR (Common Locale Data Repository) provides locale data in JSON format:

```json
// data/cldr/dates/en-US.json
{
  "locale": "en-US",
  "dates": {
    "calendars": {
      "gregorian": {
        "dateTimeFormats": {
          "full": "EEEE, MMMM d, y 'at' h:mm:ss a zzzz",
          "long": "MMMM d, y 'at' h:mm:ss a z",
          "medium": "MMM d, y, h:mm:ss a",
          "short": "M/d/yy, h:mm a"
        }
      }
    }
  }
}
```

### Data Loading

```rust
// src/data/cldr.rs

use serde::Deserialize;
use std::fs::File;
use std::io::Read;

#[derive(Debug, Deserialize)]
pub struct CldrDates {
    pub locale: String,
    pub dates: CldrDatesData,
}

#[derive(Debug, Deserialize)]
pub struct CldrDatesData {
    pub calendars: HashMap<String, CldrCalendar>,
}

#[derive(Debug, Deserialize)]
pub struct CldrCalendar {
    pub date_formats: CldrFormats,
    pub time_formats: CldrFormats,
}

#[derive(Debug, Deserialize)]
pub struct CldrFormats {
    pub full: String,
    pub long: String,
    pub medium: String,
    pub short: String,
}

pub fn load_cldr_dates(locale: &Locale) -> Result<CldrDates, LoadError> {
    let path = format!("data/cldr/dates/{}.json", locale);
    let mut file = File::open(&path)?;
    let mut contents = String::new();
    file.read_to_string(&mut contents)?;

    let cldr: CldrDates = serde_json::from_str(&contents)?;
    Ok(cldr)
}
