### Build Script

```rust
// build.rs

use std::env;
use std::fs;
use std::path::Path;

fn main() {
    println!("cargo:rerun-if-changed=data/cldr");

    let out_dir = env::var("OUT_DIR").unwrap();
    let dest_path = Path::new(&out_dir).join("generated");

    fs::create_dir_all(&dest_path).unwrap();

    // Read CLDR JSON files
    let cldr_dir = Path::new("data/cldr");
    for entry in fs::read_dir(cldr_dir).unwrap() {
        let entry = entry.unwrap();
        let path = entry.path();

        if path.extension().and_then(|s| s.to_str()) == Some("json") {
            let locale = path.file_stem().unwrap().to_str().unwrap();
            generate_locale_code(&path, &dest_path, locale);
        }
    }
}

fn generate_locale_code(source: &Path, dest: &Path, locale: &str) {
    // Read CLDR JSON
    let json = fs::read_to_string(source).unwrap();
    let cldr: CldrData = serde_json::from_str(&json).unwrap();

    // Generate Rust code
    let rust_code = format!(
        r#"
// Generated for locale: {}

pub const DATE_FORMAT_FULL: &str = {:?};
pub const DATE_FORMAT_LONG: &str = {:?};
pub const DATE_FORMAT_MEDIUM: &str = {:?};
pub const DATE_FORMAT_SHORT: &str = {:?};

pub const DECIMAL_SEPARATOR: char = {:?};
pub const GROUPING_SEPARATOR: char = {:?};
pub const GROUPING_SIZE: usize = {};
"#,
        locale,
        cldr.dates.full,
        cldr.dates.long,
        cldr.dates.medium,
        cldr.dates.short,
        cldr.numbers.decimal_separator,
        cldr.numbers.grouping_separator,
        cldr.numbers.grouping_size,
    );

    let output = dest.join(format!("{}.rs", locale.replace("-", "_")));
    fs::write(output, rust_code).unwrap();
}
```

