## Performance Considerations

### Caching Strategy

```rust
// src/data/cache.rs

use lru::LruCache;
use std::sync::Mutex;

pub struct LocaleCache {
    // LRU cache for locale data
    data: Mutex<LruCache<Locale, Arc<LocaleData>>>,

    // Format string cache
    formats: Mutex<LruCache<(Locale, FormatKey), String>>,
}

impl LocaleCache {
    pub fn new(capacity: usize) -> Self {
        Self {
            data: Mutex::new(LruCache::new(capacity)),
            formats: Mutex::new(LruCache::new(capacity * 10)),
        }
    }

    pub fn get_or_load(&self, locale: &Locale) -> Result<Arc<LocaleData>, LoadError> {
        let mut cache = self.data.lock().unwrap();

        if let Some(data) = cache.get(locale) {
            return Ok(Arc::clone(data));
        }

        let data = Arc::new(LocaleData::load(locale)?);
        cache.put(locale.clone(), Arc::clone(&data));
        Ok(data)
    }

    pub fn get_format<F>(&self, locale: &Locale, key: FormatKey, f: F) -> String
    where
        F: FnOnce() -> String
    {
        let mut cache = self.formats.lock().unwrap();
        let cache_key = (locale.clone(), key);

        if let Some(formatted) = cache.get(&cache_key) {
            return formatted.clone();
        }

        let formatted = f();
        cache.put(cache_key, formatted.clone());
        formatted
    }
}
```

### Benchmarking

```rust
// benches/format_bench.rs

use criterion::{black_box, criterion_group, criterion_main, Criterion, BenchmarkId};
use l10n::{L10n, DateStyle, NumberStyle};

fn bench_date_formatting(c: &mut Criterion) {
    let mut group = c.benchmark_group("date_formatting");

    for locale in &["en-US", "ja-JP", "de-DE"] {
        let l10n = L10n::new(locale).unwrap();
        let date = date::today();

        group.bench_with_input(
            BenchmarkId::new(locale, locale),
            &date,
            |b, date| {
                b.iter(|| {
                    black_box(l10n.format_date(black_box(date), DateStyle::Long))
                })
            },
        );
    }

    group.finish();
}

fn bench_number_formatting(c: &mut Criterion) {
    let l10n = L10n::new("en-US").unwrap();

    c.bench_function("number_formatting", |b| {
        b.iter(|| {
            black_box(l10n.format_number(1234.56, NumberStyle::Standard))
        })
    });
}

criterion_group!(benches, bench_date_formatting, bench_number_formatting);
criterion_main!(benches);
```

### Performance Guidelines

1. **Reuse L10n instances**: Don't create new instances for each format operation

```rust
// Bad
for i in 0..1000 {
    let l10n = L10n::new("en-US").unwrap();
    l10n.format_number(i as f64, NumberStyle::Standard);
}

// Good
let l10n = L10n::new("en-US").unwrap();
for i in 0..1000 {
    l10n.format_number(i as f64, NumberStyle::Standard);
}
```

2. **Use appropriate styles**: Some styles are more expensive than others

```rust
// Short is faster than Full
l10n.format_date(&date, DateStyle::Short);  // Fast
l10n.format_date(&date, DateStyle::Full);   // Slower
```

3. **Enable caching for repeated operations**

```rust
let l10n = L10n::builder()
    .cache_enabled(true)
    .build()
    .unwrap();
```

