## 🔧 Common Tasks

### Format Dates and Times

```rust
use l10n::{L10n, DateStyle, TimeStyle};

let l10n = L10n::new("en-US").unwrap();

// Date: "January 9, 2025"
l10n.format_date(&date, DateStyle::Long);

// Time: "3:30 PM"
l10n.format_time(&time, TimeStyle::Short);

// DateTime: "Jan 9, 2025, 3:30 PM"
l10n.format_datetime(&datetime, DateStyle::Medium, TimeStyle::Short);

// Relative: "2 hours ago"
l10n.format_relative(&datetime);
```

### Format Numbers and Currency

```rust
use l10n::{L10n, NumberStyle};

let l10n = L10n::new("en-US").unwrap();

// Number: "1,234.56"
l10n.format_number(1234.56, NumberStyle::Standard);

// Currency: "$99.99"
l10n.format_currency(99.99, "USD");

// Percent: "45.67%"
l10n.format_percent(0.4567);

// Compact: "1.2K", "1.5M"
