### Validate Phone Numbers

```rust
use l10n::L10n;

let l10n = L10n::new("en-US").unwrap();

// Validate and parse
match l10n.validate_phone("555-123-4567", "US") {
    Ok(phone) => {
        println!("Valid: {}",
            l10n.format_phone(&phone, PhoneStyle::National));
    }
    Err(errors) => {
        eprintln!("Invalid: {:?}", errors);
    }
}
```

### Format Addresses

```rust
use l10n::{L10n, Address};

let l10n = L10n::new("en-US").unwrap();

let address = Address {
    recipient: Some("John Smith".to_string()),
    street: Some("123 Main St".to_string()),
    city: Some("Springfield".to_string()),
    region: Some("IL".to_string()),
