### Global E-commerce

```rust
use l10n::L10n;

let products = vec![
    (99.99, "USD", "en-US"),
    (99.99, "EUR", "de-DE"),
    (1000.0, "JPY", "ja-JP"),
];

for (price, currency, locale) in products {
    let l10n = L10n::new(locale).unwrap();
    println!("{}", l10n.format_currency(price, currency));
    // $99.99
    // 99,99 €
    // ¥1,000
}
```

