fn main() {
    let unique_users = Set::new("unique_users")
        .help("Unique users in last hour")
        .build();

    // Track users
    unique_users.insert("alice");
    unique_users.insert("bob");
    unique_users.insert("alice"); // Duplicate

    println!("Unique users: {}", unique_users.len());

    // Print in Prometheus format
