## Testing Guide

### Unit Tests

**Coverage Goal**: 100% for core functionality.

**Example**:

```rust
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_counter_inc() {
        let counter = Counter::new("test_counter").build();
        counter.inc();
        assert_eq!(counter.get(), 1);
    }

    #[test]
    fn test_counter_inc_by() {
        let counter = Counter::new("test_counter").build();
        counter.inc_by(5);
        assert_eq!(counter.get(), 5);
    }

    #[test]
    fn test_counter_concurrent() {
        let counter = Arc::new(Counter::new("test_counter").build());
        let mut handles = vec![];

        for _ in 0..100 {
            let counter = counter.clone();
            handles.push(std::thread::spawn(move || {
                counter.inc();
            }));
        }

        for handle in handles {
            handle.join().unwrap();
        }

        assert_eq!(counter.get(), 100);
    }
}
```

