### Integration Tests

**Goal**: Test end-to-end workflows.

Create `tests/integration.rs`:

```rust
use metrics::{Counter, Histogram, Registry};

#[test]
fn test_metric_registration() {
    let registry = Registry::new();
    let counter = Counter::new("test_counter")
        .registry(registry.clone())
        .build();

    counter.inc();

    let metrics = registry.scrape();
    assert!(metrics.contains("test_counter"));
    assert!(metrics.contains("1"));
}

#[test]
fn test_prometheus_format() {
    let registry = Registry::new();
    let counter = Counter::new("requests_total")
        .registry(registry.clone())
        .help("Total requests")
        .build();

    counter.inc();

    let metrics = registry.scrape();

    // Check HELP line
    assert!(metrics.contains("# HELP requests_total Total requests"));

    // Check TYPE line
    assert!(metrics.contains("# TYPE requests_total counter"));

    // Check metric line
    assert!(metrics.contains("requests_total{} 1"));
}
```

