### Performance Tests

**Goal**: Verify performance targets.

Use `criterion` crate:

```toml
[dev-dependencies]
criterion = "0.5"

[[bench]]
name = "counter"
harness = false
```

Create `benches/counter.rs`:

```rust
use criterion::{black_box, criterion_group, criterion_main, Criterion, BenchmarkId};
use metrics::Counter;

fn bench_counter_inc(c: &mut Criterion) {
    let mut group = c.benchmark_group("counter");

    group.bench_function("inc", |b| {
        let counter = Counter::new("bench_counter").build();
        b.iter(|| {
            counter.inc();
        });
    });

    group.bench_function("inc_by", |b| {
        let counter = Counter::new("bench_counter").build();
        b.iter(|| {
            counter.inc_by(black_box(5));
        });
    });

    group.finish();
}

fn bench_counter_concurrent(c: &mut Criterion) {
    let mut group = c.benchmark_group("counter_concurrent");

    for threads in [1, 2, 4, 8].iter() {
        group.bench_with_input(BenchmarkId::from_parameter(threads), threads, |b, &threads| {
            let counter = std::sync::Arc::new(Counter::new("bench_counter").build());

            b.iter(|| {
                let mut handles = vec![];
                for _ in 0..threads {
                    let counter = counter.clone();
                    handles.push(std::thread::spawn(move || {
                        for _ in 0..1000 {
                            counter.inc();
                        }
                    }));
                }
                for handle in handles {
                    handle.join().unwrap();
                }
            });
        });
    }

    group.finish();
}

criterion_group!(benches, bench_counter_inc, bench_counter_concurrent);
criterion_main!(benches);
```

**Run Benchmarks**:

```bash
cargo bench
```

**Expected Results**:
- `inc`: <10ns/iter
- `inc_by`: <10ns/iter
- Concurrent: Linear speedup with threads

