        // Set up timer
        Ok(())
    }
}
```

**Usage**:
```rust
let sampler = FixedRateSampler::new(Hz(100));
// Always samples at 100 Hz
```

### Adaptive Sampling

```rust
pub struct AdaptiveSampler {
    target_overhead: Percentage,
    current_frequency: Hz,
    overhead_monitor: OverheadMonitor,
}

impl AdaptiveSampler {
    pub fn new(target_overhead: Percentage) -> Self {
        Self {
            target_overhead,
            current_frequency: Hz(100),
            overhead_monitor: OverheadMonitor::new(),
        }
    }

    pub fn adjust_sampling(&mut self) {
        let overhead = self.overhead_monitor.current_overhead();

        if overhead > self.target_overhead {
            // Reduce sampling rate
            self.current_frequency = Hz(self.current_frequency.0 / 2);
        } else if overhead < self.target_overhead / 2 {
            // Increase sampling rate
            self.current_frequency = Hz(self.current_frequency.0 * 2);
        }
    }
}
```

**Usage**:
```rust
let sampler = AdaptiveSampler::new(Percentage(5.0));
// Adjusts rate to maintain ~5% overhead
```

### Stratified Sampling

