## Platform-Specific Code

### Linux (perf_events)

```rust
use libc::{perf_event_attr, perf_event_open, ioctl};

pub struct LinuxSampler {
    perf_fd: i32,
    frequency: Hz,
}

impl LinuxSampler {
    pub fn new(frequency: Hz) -> Result<Self> {
        let mut attr = perf_event_attr {
            type_: PERF_TYPE_HARDWARE,
            config: PERF_COUNT_HW_CPU_CYCLES,
            freq: 1,
            sample_freq: frequency.0 as u64,
            sample_type: PERF_SAMPLE_CALLCHAIN,
            ..Default::default()
        };

        let perf_fd = unsafe {
            perf_event_open(
                &attr,
                -1,  // All PIDs
                -1,  // All CPUs
                -1,  // No group leader
                0,   // Flags
            )
        };

        if perf_fd < 0 {
            return Err(ProfilerError::PlatformError("perf_event_open failed".into()));
        }

        unsafe {
            ioctl(perf_fd, PERF_EVENT_IOC_RESET, 0);
            ioctl(perf_fd, PERF_EVENT_IOC_ENABLE, 0);
        }

        Ok(Self { perf_fd, frequency })
    }

    pub fn read_samples(&mut self) -> Vec<RawSample> {
        // Read from perf event fd
        // Parse perf sample format
        vec![]
    }
}

impl Drop for LinuxSampler {
    fn drop(&mut self) {
        unsafe {
            ioctl(self.perf_fd, PERF_EVENT_IOC_DISABLE, 0);
            libc::close(self.perf_fd);
        }
    }
}
```

