        }

        Ok(Self { kdebug_fd, frequency })
    }

    pub fn read_samples(&mut self) -> Vec<RawSample> {
        // Read from kdebug trace buffer
        vec![]
    }
}

extern "C" {
    fn kdebug_trace_enable(
        type_: u32,
        scale: u32,
        buf_size: u32,
    ) -> i32;
}
```

### Windows (ETW)

