## Production Profiling

### Use Case: Production Server Monitoring

**Problem**: Production server slow, need to diagnose

**Solution**: Low-overhead continuous profiling

```rust
use profiler::{Profiler, Hz};

fn main() -> Result<()> {
    // Very low overhead for production
    let profiler = Profiler::with_config(
        Config::builder()
            .sampling_frequency(Hz(10))  // 10 Hz = <1% overhead
            .continuous()
            .target_overhead(1.0)  // Aim for 1% overhead
            .output_file("production.prof")
            .build()
    )?;

    // Run production server
    run_server()?;

    Ok(())
}

// Or enable dynamically via signal
use std::signal::{ctrl_c, Signal};

fn main() -> Result<()> {
    let mut profiler = None;

    // Handle SIGUSR2 (toggle profiling)
    signal::register(Signal::User2, || {
        if profiler.is_none() {
            profiler = Some(Profiler::start().unwrap());
            eprintln!("Profiling started");
        } else {
            let profile = profiler.take().unwrap().stop().unwrap();
            profile.save_to_file("on_demand.prof").ok();
            eprintln!("Profile saved");
        }
    })?;

    run_server()?;

    Ok(())
}
```

### Use Case: A/B Testing Performance

**Problem**: Compare two implementations in production

**Solution**: Profile both variants

```rust
use profiler::{Profiler, profile};

async fn handle_request_variant_a(req: Request) -> Response {
    let (result, _profile) = profile(|| {
        process_variant_a(req)
    });
    result
}

async fn handle_request_variant_b(req: Request) -> Response {
    let (result, _profile) = profile(|| {
        process_variant_b(req)
    });
    result
}

// Later: Compare profiles
fn compare_variants() {
    let profile_a = Profile::load_from_file("variant_a.prof").unwrap();
    let profile_b = Profile::load_from_file("variant_b.prof").unwrap();

    let report = profile_b.compare(&profile_a);

    for regression in report.regressions {
        println!("B is slower in {}", regression.function);
    }
}
```

