fn main() -> Result<()> {
    let db = VectorDatabase::connect("profiles")?;

    let profiler = Profiler::with_search(db)?;

    run_application();

    let current_profile = profiler.stop()?;

    // Find similar historical profiles
    let similar = profiler.find_similar(&current_profile, 5)?;

    for (profile, similarity) in similar {
