## Custom Prompt Development

### Creating a Custom Prompt

To create a custom prompt, implement the `Prompt` trait:

```rust
use prompt_rs::{Prompt, Result, PromptState};
use prompt_rs::terminal::{Terminal, Event};

pub struct DatePicker {
    message: String,
    selected_date: Option<chrono::NaiveDate>,
    current_view: CalendarView,
}

impl DatePicker {
    pub fn new(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            selected_date: None,
            current_view: CalendarView::Month,
        }
    }
}

impl Prompt for DatePicker {
    type Output = chrono::NaiveDate;

    fn id(&self) -> &str {
        "date_picker"
    }

    async fn run(&self) -> Result<Self::Output> {
        let mut terminal = Terminal::new()?;
        let mut engine = AsyncEngine::new(terminal);

        let mut state = PromptState::Initializing;

        // Render initial state
        self.render(&mut engine.terminal)?;

        loop {
            let event = engine.terminal.read_event().await?;
            state = self.handle_event(event, &mut engine.terminal)?;

            match state {
                PromptState::Complete(date) => return Ok(date),
                PromptState::Cancelled => return Err(Error::Cancelled),
                _ => continue,
            }
        }
    }
}

impl DatePicker {
    fn render(&self, terminal: &mut Terminal) -> Result<()> {
        terminal.clear()?;
        terminal.write(&self.message)?;
        terminal.write("\n")?;

        // Render calendar
        let calendar = self.render_calendar();
        terminal.write(&calendar)?;

        terminal.move_cursor_to_prompt()?;
        Ok(())
    }

    fn handle_event(
        &mut self,
        event: Event,
        terminal: &mut Terminal,
    ) -> Result<PromptState<chrono::NaiveDate>> {
        match event {
            Event::Key(Key::Char('\n')) => {
                if let Some(date) = self.selected_date {
                    Ok(PromptState::Complete(date))
                } else {
                    Ok(PromptState::WaitingForInput)
                }
            }
            Event::Key(Key::Esc) => Ok(PromptState::Cancelled),
            Event::Key(Key::Up) => {
                self.move_selection(-7); // Move up one week
                self.render(terminal)?;
                Ok(PromptState::WaitingForInput)
            }
            Event::Key(Key::Down) => {
                self.move_selection(7); // Move down one week
                self.render(terminal)?;
                Ok(PromptState::WaitingForInput)
            }
            Event::Key(Key::Left) => {
                self.move_selection(-1); // Move back one day
                self.render(terminal)?;
                Ok(PromptState::WaitingForInput)
            }
            Event::Key(Key::Right) => {
                self.move_selection(1); // Move forward one day
                self.render(terminal)?;
                Ok(PromptState::WaitingForInput)
            }
            _ => Ok(PromptState::WaitingForInput),
        }
    }

    fn render_calendar(&self) -> String {
        // Render calendar UI
        // ... implementation details
        String::from("Calendar UI here")
    }

    fn move_selection(&mut self, days: i32) {
        // Update selected date
        // ... implementation details
    }
}
```

### Using Your Custom Prompt

```rust
#[tokio::main]
async fn main() -> Result<()> {
    let date = DatePicker::new("Select a date")
        .run()
        .await?;

    println!("Selected: {}", date);
    Ok(())
}
```

