## Validation Strategies

### Synchronous Validation

For fast, in-memory validation:

```rust
use prompt_rs::validation::Validation;

pub struct RequiredValidator;

impl Validation<String> for RequiredValidator {
    fn validate(&self, input: &String) -> ValidationResult {
        if input.is_empty() {
            Err("This field is required".to_string())
        } else {
            Ok(())
        }
    }

    fn hint(&self) -> Option<String> {
        Some("Enter a value".to_string())
    }
}
```

### Asynchronous Validation

For slower validation (API calls, database checks):

```rust
use prompt_rs::validation::AsyncValidation;

pub struct UsernameAvailabilityValidator {
    db: Database,
}

impl AsyncValidation<String> for UsernameAvailabilityValidator {
    fn validate(&self, input: &String) -> Pin<Box<dyn Future<Output = ValidationResult> + Send>> {
        let db = self.db.clone();
        let username = input.clone();

        Box::pin(async move {
            match db.check_username_available(&username).await {
                Ok(true) => Ok(()),
                Ok(false) => Err("Username is already taken".to_string()),
                Err(_) => Err("Could not check username availability".to_string()),
            }
        })
    }
}
```

### Composite Validation

Combine multiple validators:

```rust
use prompt_rs::validation::{Validation, ValidationResult, all_of};

pub struct CompositeValidator {
    validators: Vec<Box<dyn Validation<String>>>,
}

impl Validation<String> for CompositeValidator {
    fn validate(&self, input: &String) -> ValidationResult {
        for validator in &self.validators {
            validator.validate(input)?;
        }
        Ok(())
    }

    fn error_message(&self) -> Option<String> {
        // Aggregate all error messages
        let errors: Vec<_> = self.validators
            .iter()
            .filter_map(|v| v.error_message())
            .collect();

        if errors.is_empty() {
            None
        } else {
            Some(errors.join("; "))
        }
    }
}

// Usage
let validator = CompositeValidator {
    validators: vec![
        Box::new(RequiredValidator),
        Box::new(LengthValidator { min: 3, max: 20 }),
        Box::new(PatternValidator {
            pattern: Regex::new(r"^[a-zA-Z0-9_]+$").unwrap(),
            message: "Only letters, numbers, and underscores".to_string(),
        }),
    ],
};
```

### Validation with Context

Pass context to validators:

```rust
pub trait ContextValidation<T, C>: Validation<T> {
    fn with_context(self, context: C) -> ContextValidator<T, C, Self>
    where
        Self: Sized,
    {
        ContextValidator {
            validator: self,
            context,
        }
    }
}

pub struct ContextValidator<T, C, V> {
    validator: V,
    context: C,
}

impl<T, C, V> Validation<T> for ContextValidator<T, C, V>
where
    V: Validation<T>,
    C: Clone,
{
    fn validate(&self, input: &T) -> ValidationResult {
        // Use context in validation
        self.validator.validate(input)
    }
}

// Usage
let validator = UniqueUsernameValidator
    .with_context(DatabaseContext::new());
```

