## Testing Prompts

### Unit Testing with Mock Terminal

```rust
#[cfg(test)]
mod tests {
    use super::*;
    use prompt_rs::testing::MockTerminal;

    #[tokio::test]
    async fn test_input_prompt() {
        let mut terminal = MockTerminal::new();
        terminal.simulate_input("Alice\n");

        let prompt = InputPrompt::new("Name");
        let result = prompt.run_with_terminal(&mut terminal).await;

        assert_eq!(result.unwrap(), "Alice");
    }

    #[tokio::test]
    async fn test_validation() {
        let mut terminal = MockTerminal::new();
        terminal.simulate_inputs(&["", "ab", "Alice"]);

        let prompt = InputPrompt::new("Name")
            .validate(|s| {
                if s.len() < 3 {
                    Err("Name too short".to_string())
                } else {
                    Ok(())
                }
            });

        let result = prompt.run_with_terminal(&mut terminal).await;

        assert_eq!(result.unwrap(), "Alice");
        assert_eq!(terminal.error_messages().len(), 2);
    }

    #[tokio::test]
    async fn test_select_prompt() {
        let mut terminal = MockTerminal::new();
        terminal.simulate_keys(&[Key::Down, Key::Down, Key::Char('\n')]);

        let prompt = SelectPrompt::new("Choose", vec!["A", "B", "C"]);
        let result = prompt.run_with_terminal(&mut terminal).await;

        assert_eq!(result.unwrap(), "B");
    }
}
