## Performance Optimization

### Render Caching

```rust
pub struct CachedRenderer {
    cache: HashMap<String, RenderedOutput>,
    last_render: Option<String>,
}

impl CachedRenderer {
    pub fn render(&mut self, id: &str, content: &str) -> Result<()> {
        let hash = format!("{}:{}", id, content);

        if self.last_render.as_ref() == Some(&hash) {
            // Skip rendering (no change)
            return Ok(());
        }

        // Check cache
        if let Some(cached) = self.cache.get(&hash) {
            self.terminal.write(cached)?;
            return Ok(());
        }

        // Render and cache
        let output = self.render_content(content)?;
        self.cache.insert(hash, output.clone());
        self.terminal.write(&output)?;

        self.last_render = Some(hash);
        Ok(())
    }
}
```

### Debounced Validation

```rust
pub struct DebouncedValidator {
    debounce_duration: Duration,
    last_input: String,
    last_validation: Instant,
}

impl DebouncedValidator {
    pub fn should_validate(&mut self, input: &str) -> bool {
        let input_changed = self.last_input != input;
        let debounce_passed = self.last_validation.elapsed() >= self.debounce_duration;

        input_changed && debounce_passed
    }

    pub async fn validate(&mut self, input: &str) -> ValidationResult {
        self.last_input = input.to_string();
        self.last_validation = Instant::now();
        // Perform validation
    }
}
```

### Virtual Scrolling

For long lists:

```rust
pub struct VirtualScroll<T> {
    items: Vec<T>,
    page_size: usize,
    offset: usize,
}

impl<T> VirtualScroll<T> {
    pub fn visible_items(&self) -> &[T] {
        let start = self.offset;
        let end = (self.offset + self.page_size).min(self.items.len());
        &self.items[start..end]
    }

    pub fn scroll_down(&mut self) {
        let max_offset = self.items.len().saturating_sub(self.page_size);
        self.offset = (self.offset + 1).min(max_offset);
    }

    pub fn scroll_up(&mut self) {
        self.offset = self.offset.saturating_sub(1);
    }
}
```

