## 3. Adding Custom Algorithms

### 3.1 Algorithm Template

Create a new file `src/algorithm/my_algorithm.rs`:

```rust
use crate::algorithm::{Algorithm, AlgorithmState, LimitResult};
use std::time::{Duration, Instant};

pub struct MyAlgorithm {
    // Your configuration here
    limit: u32,
    window: Duration,
}

impl MyAlgorithm {
    pub fn new(limit: u32, window: Duration) -> Self {
        Self { limit, window }
    }
}

impl Algorithm for MyAlgorithm {
    fn check(
        &self,
        _key: &str,
        state: &mut AlgorithmState,
        tokens: u32,
    ) -> LimitResult {
        // Get algorithm-specific state
        let my_state = match state {
            AlgorithmState::MyCustomState { data } => data,
            _ => panic!("Invalid state type"),
        };

        // Implement your algorithm logic here
        let now = Instant::now();

        if my_state.count + tokens <= self.limit {
            // Allow request
            my_state.count += tokens;

            LimitResult::Allowed {
                remaining: self.limit - my_state.count,
                reset_at: my_state.window_start + self.window,
            }
        } else {
            // Deny request
            let retry_after = my_state.window_start + self.window - now;
            LimitResult::Denied { retry_after }
        }
    }

    fn reset(&self, state: &mut AlgorithmState) {
        *state = self.initial_state();
    }

    fn initial_state(&self) -> AlgorithmState {
        AlgorithmState::MyCustomState {
            count: 0,
            window_start: Instant::now(),
        }
    }

    fn memory_per_key(&self) -> usize {
        std::mem::size_of::<u32>() + std::mem::size_of::<Instant>()
    }
}
```

### 3.2 Add State Enum

Update `src/result.rs`:

