#[async_trait]
impl Backend for MyBackend {
    async fn load_state(
        &self,
        key: &str,
        init: impl Fn() -> AlgorithmState,
    ) -> Result<Box<AlgorithmState>, BackendError> {
        // Try to load from your backend
        match self.load_from_backend(key).await {
            Ok(Some(data)) => {
                // Deserialize state
                let state = self.deserialize_state(&data)?;
                Ok(Box::new(state))
            }
            Ok(None) => {
                // Key doesn't exist, create initial state
                let state = init();
                self.save_to_backend(key, &state).await?;
                Ok(Box::new(state))
            }
            Err(e) => Err(e),
        }
    }

    async fn save_state(
        &self,
