        self.save_to_backend(key, &data).await
    }

    async fn reset_state(&self, key: &str) -> Result<(), BackendError> {
        self.delete_from_backend(key).await
    }

    async fn exists(&self, key: &str) -> Result<bool, BackendError> {
        self.check_exists(key).await
    }

