use criterion::{black_box, criterion_group, criterion_main, Criterion, BenchmarkId};
use ratelimit::{RateLimiter, Algorithm};
use std::time::Duration;

fn benchmark_token_bucket(c: &mut Criterion) {
    let mut group = c.benchmark_group("token_bucket");

    for capacity in [10, 100, 1000].iter() {
        group.bench_with_input(
            BenchmarkId::new("check", capacity),
            capacity,
            |b, &capacity| {
                let rt = tokio::runtime::Runtime::new().unwrap();
                let limiter = rt.block_on(async {
                    RateLimiter::new(Algorithm::TokenBucket {
                        capacity,
                        refill_rate: *capacity,
                    })
                });

                b.to_async(rt).iter(|| async {
                    limiter.check("test").await.unwrap()
                });
            },
        );
    }

    group.finish();
}

