## Example 1: Basic Token Bucket

The simplest rate limiting example.

```rust
use ratelimit::{RateLimiter, Algorithm};
use std::time::Duration;
use tokio;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Create rate limiter: 10 tokens capacity, 10 refill per second
    let limiter = RateLimiter::new(Algorithm::TokenBucket {
        capacity: 10,
        refill_rate: 10,
    });

    println!("Testing token bucket rate limiter...\n");

    // Make 10 requests (all should be allowed)
    for i in 1..=10 {
        match limiter.check("user-123").await? {
            ratelimit::LimitResult::Allowed { remaining, .. } => {
                println!("Request {}: ✓ Allowed ({} remaining)", i, remaining);
            }
            ratelimit::LimitResult::Denied { .. } => {
                println!("Request {}: ✗ Denied", i);
            }
        }
    }

    println!("\nCapacity exhausted. Waiting 1 second for refill...\n");

    // Wait for tokens to refill
    tokio::time::sleep(Duration::from_secs(1)).await;

    // Should be allowed again
    match limiter.check("user-123").await? {
        ratelimit::LimitResult::Allowed { remaining, .. } => {
            println!("Request 11: ✓ Allowed ({} remaining)", remaining);
        }
        ratelimit::LimitResult::Denied { .. } => {
            println!("Request 11: ✗ Denied");
        }
    }

    Ok(())
}
```

**Output:**
```
Testing token bucket rate limiter...

Request 1: ✓ Allowed (9 remaining)
Request 2: ✓ Allowed (8 remaining)
...
Request 10: ✓ Allowed (0 remaining)

Capacity exhausted. Waiting 1 second for refill...

Request 11: ✓ Allowed (9 remaining)
```

