## Example 4: Distributed Rate Limiting with Flashcache

Share rate limit state across multiple processes.

```rust
use ratelimit::{RateLimiter, Algorithm};
use ratelimit::backend::FlashcacheBackend;
use std::time::Duration;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Connect to flashcache (Redis)
    let backend = FlashcacheBackend::builder()
        .url("redis://localhost:6379")
        .ttl(Duration::from_secs(3600))
        .build()
        .await?;

    // Create distributed rate limiter
    let limiter = RateLimiter::with_backend(
        Algorithm::SlidingWindowCounter {
            limit: 1000,
            window: Duration::from_secs(60),
        },
        backend,
    ).await?;

    println!("Testing distributed rate limiter...\n");

    // Simulate requests from multiple processes
    for process_id in 1..=3 {
        let limiter_clone = limiter.clone();
        tokio::spawn(async move {
            for i in 1..=50 {
                let key = format!("process-{}-req-{}", process_id, i);
                match limiter_clone.check(&key).await {
                    Ok(ratelimit::LimitResult::Allowed { remaining, .. }) => {
                        println!("Process {}: Request {} allowed ({} remaining)",
                                 process_id, i, remaining);
                    }
                    Ok(ratelimit::LimitResult::Denied { .. }) => {
                        println!("Process {}: Request {} denied", process_id, i);
                    }
                    Err(e) => {
                        eprintln!("Process {}: Error: {}", process_id, e);
                    }
                }
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        });
    }

    // Wait for all processes to complete
    tokio::time::sleep(Duration::from_secs(5)).await;

    println!("\nDistributed rate limiting works across multiple processes!");

    Ok(())
}
```

