## Example 5: Actix-web Middleware

Protect your Actix-web API with rate limiting.

```rust
use actix_web::{web, App, HttpServer, HttpResponse, Result};
use ratelimit::{RateLimiter, Algorithm};
use ratelimit::middleware::actix::RateLimitMiddleware;
use std::time::Duration;

async fn index() -> Result<HttpResponse> {
    Ok(HttpResponse::Ok().json(json!({
        "message": "Hello, World!",
        "timestamp": chrono::Utc::now()
    })))
}

async fn protected_data() -> Result<HttpResponse> {
    Ok(HttpResponse::Ok().json(json!({
        "data": "This is protected data"
    })))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    // Create rate limiter
    let limiter = RateLimiter::new(Algorithm::SlidingWindowCounter {
        limit: 100,
        window: Duration::from_secs(60),
    });

    // Create middleware
    let middleware = RateLimitMiddleware::new(limiter)
        .on_exceed(|_req| async {
            HttpResponse::TooManyRequests().json(json!({
                "error": "Rate limit exceeded",
                "message": "Too many requests. Please try again later.",
                "retry_after": 60
            }))
        });

    println!("Starting server on http://localhost:8080");

    HttpServer::new(move || {
        App::new()
            .wrap(middleware.clone())
            .route("/", web::get().to(index))
            .route("/api/data", web::get().to(protected_data))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
```

**Test it:**
