## Example 7: Adaptive Rate Limiting

Adjust limits based on system load.

```rust
use ratelimit::{RateLimiter, Algorithm};
use std::time::Duration;

struct AdaptiveRateLimiter {
    normal_limiter: RateLimiter,
    reduced_limiter: RateLimiter,
    load_threshold: f64,
}

impl AdaptiveRateLimiter {
    fn new() -> Self {
        Self {
            normal_limiter: RateLimiter::new(Algorithm::TokenBucket {
                capacity: 1000,
                refill_rate: 100,
            }),
            reduced_limiter: RateLimiter::new(Algorithm::TokenBucket {
                capacity: 100,
                refill_rate: 10,
            }),
            load_threshold: 0.8, // 80% load threshold
        }
    }

    async fn check(&self, user_id: &str) -> Result<ratelimit::LimitResult, Box<dyn std::error::Error>> {
        // Get current system load (simplified)
        let system_load = get_system_load().await;

        let limiter = if system_load > self.load_threshold {
            println!("High system load detected ({:.2}), using reduced rate limit", system_load);
            &self.reduced_limiter
        } else {
            &self.normal_limiter
        };

        limiter.check(user_id).await
    }
}

async fn get_system_load() -> f64 {
    // Simplified: get CPU load
    // In production, use actual system metrics
    0.75
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let adaptive_limiter = AdaptiveRateLimiter::new();

    println!("Testing adaptive rate limiting...\n");

    // Normal load
    for i in 1..=10 {
        match adaptive_limiter.check("user-123").await? {
            ratelimit::LimitResult::Allowed { remaining, .. } => {
                println!("Request {}: ✓ Allowed ({} remaining)", i, remaining);
            }
            ratelimit::LimitResult::Denied { .. } => {
                println!("Request {}: ✗ Denied", i);
            }
        }
    }

    Ok(())
}
```

---

## Example 8: Multi-Stage Rate Limiting

Multiple layers of rate limiting.

```rust
use ratelimit::{RateLimiter, Algorithm};
use std::time::Duration;

struct MultiStageLimiter {
    per_second: RateLimiter,
    per_minute: RateLimiter,
    per_hour: RateLimiter,
}

impl MultiStageLimiter {
    fn new() -> Self {
        Self {
            // 10 requests per second
            per_second: RateLimiter::new(Algorithm::TokenBucket {
                capacity: 10,
                refill_rate: 10,
            }),
            // 100 requests per minute
            per_minute: RateLimiter::new(Algorithm::SlidingWindowCounter {
                limit: 100,
                window: Duration::from_secs(60),
            }),
            // 1000 requests per hour
            per_hour: RateLimiter::new(Algorithm::SlidingWindowCounter {
                limit: 1000,
                window: Duration::from_secs(3600),
            }),
        }
    }

    async fn check(&self, user_id: &str) -> Result<ratelimit::LimitResult, Box<dyn std::error::Error>> {
        // Stage 1: Per-second limit
        let result1 = self.per_second.check(&format!("{}:1s", user_id)).await?;
        if result1.is_denied() {
            return Ok(result1);
        }

        // Stage 2: Per-minute limit
        let result2 = self.per_minute.check(&format!("{}:1m", user_id)).await?;
        if result2.is_denied() {
            return Ok(result2);
        }

        // Stage 3: Per-hour limit
        self.per_hour.check(&format!("{}:1h", user_id)).await
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let limiter = MultiStageLimiter::new();

    println!("Testing multi-stage rate limiting...\n");

    // Make 15 requests rapidly
    for i in 1..=15 {
        match limiter.check("user-456").await? {
            ratelimit::LimitResult::Allowed { .. } => {
                println!("Request {}: ✓ Allowed", i);
            }
            ratelimit::LimitResult::Denied { .. } => {
                println!("Request {}: ✗ Denied", i);
            }
        }

        // Small delay
        tokio::time::sleep(Duration::from_millis(50)).await;
    }

    Ok(())
}
```

---

## Example 9: Rate Limit with Metrics

Export Prometheus metrics for rate limiting.

```rust
use ratelimit::{RateLimiter, Algorithm};
use ratelimit::observability::metrics::{MetricsRecorder, PrometheusMetrics};
use prometheus::{Counter, Histogram, Registry};
use std::time::Duration;

struct MyMetrics {
    allowed: Counter,
    denied: Counter,
    duration: Histogram,
}

impl MyMetrics {
    fn new() -> Self {
        let allowed = Counter::new("requests_allowed_total", "Total allowed requests").unwrap();
        let denied = Counter::new("requests_denied_total", "Total denied requests").unwrap();
        let duration = Histogram::new("rate_limit_duration_seconds", "Rate limit check duration").unwrap();

        let registry = prometheus::default_registry();
        registry.register(Box::new(allowed.clone())).unwrap();
        registry.register(Box::new(denied.clone())).unwrap();
        registry.register(Box::new(duration.clone())).unwrap();

        Self { allowed, denied, duration }
    }
}

impl MetricsRecorder for MyMetrics {
    fn record_allowed(&self, _key: &str, _algorithm: &str) {
        self.allowed.inc();
    }

    fn record_denied(&self, _key: &str, _algorithm: &str) {
        self.denied.inc();
    }

    fn record_check_duration(&self, _key: &str, duration: Duration) {
        self.duration.observe(duration.as_secs_f64());
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let metrics = MyMetrics::new();

    let limiter = RateLimiter::new(Algorithm::TokenBucket {
        capacity: 10,
        refill_rate: 10,
    }).with_metrics(metrics);

    println!("Testing rate limiting with metrics...\n");

    // Make requests
    for i in 1..=15 {
        match limiter.check("user-789").await? {
            ratelimit::LimitResult::Allowed { .. } => {
                println!("Request {}: ✓ Allowed", i);
            }
            ratelimit::LimitResult::Denied { .. } => {
                println!("Request {}: ✗ Denied", i);
            }
        }
    }

    println!("\nMetrics:");
    println!("✓ Prometheus metrics exported");
    println!("✓ Visit http://localhost:9090/metrics to view");

    Ok(())
}
```

---

## Example 10: Custom Key Extractor

Extract rate limit keys from custom request data.

```rust
use ratelimit::{RateLimiter, Algorithm, key::KeyExtractor, Request, KeyError};
use std::collections::HashMap;

// Custom key extractor that combines user ID and endpoint
struct CustomExtractor;

impl KeyExtractor for CustomExtractor {
    fn extract_key(&self, request: &Request) -> Result<String, KeyError> {
        // Extract user ID from header
        let user_id = request.headers.get("X-User-ID")
            .ok_or_else(|| KeyError::HeaderMissing("X-User-ID".to_string()))?;

        // Extract endpoint from URI
        let endpoint = request.uri.split('?').next().unwrap_or("/");

        // Combine user ID and endpoint
        Ok(format!("user:{}:endpoint:{}", user_id, endpoint))
    }

    fn key_type(&self) -> &'static str {
        "custom"
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let limiter = RateLimiter::new(Algorithm::TokenBucket {
        capacity: 100,
        refill_rate: 10,
    }).with_key_extractor(Box::new(CustomExtractor));

    // Create test request
    let mut request = Request {
        method: "GET".to_string(),
        uri: "/api/data".to_string(),
        headers: HashMap::new(),
        body: vec![],
        remote_addr: None,
    };

    request.headers.insert("X-User-ID".to_string(), "user-123".to_string());

    // Extract key
    let key_extractor = CustomExtractor;
    let key = key_extractor.extract_key(&request)?;
    println!("Extracted key: {}", key);

    // Check rate limit
    match limiter.check(&key).await? {
        ratelimit::LimitResult::Allowed { remaining, .. } => {
            println!("✓ Allowed ({} remaining)", remaining);
        }
        ratelimit::LimitResult::Denied { .. } => {
            println!("✗ Denied");
        }
    }

    Ok(())
}
```

