## Example 2: Traffic Light Controller

**State machine with timing and actions**

```rust
use statemachine::{StateMachine, State, Event, Transitionable, TransitionError, actions};
use std::time::Duration;
use std::thread;

// Define states
struct Red;
struct Yellow;
struct Green;

impl State for Red {
    type Data = Duration;
    type Parent = ();
}

impl State for Yellow {
    type Data = Duration;
    type Parent = ();
}

impl State for Green {
    type Data = Duration;
    type Parent = ();
}

// Define events
struct Timer;
impl Event for Timer {}

// Define transitions
impl Transitionable<Timer> for Red {
    type Next = Green;

    fn transition(self, _event: Timer) -> Result<StateMachine<Green>, TransitionError> {
        println!("🚦 Red → Green");
        Ok(StateMachine::with_state_data(Duration::from_secs(10)))
    }
}

impl Transitionable<Timer> for Green {
    type Next = Yellow;

    fn transition(self, _event: Timer) -> Result<StateMachine<Yellow>, TransitionError> {
        println!("🚦 Green → Yellow");
        Ok(StateMachine::with_state_data(Duration::from_secs(3)))
    }
}

impl Transitionable<Timer> for Yellow {
    type Next = Red;

    fn transition(self, _event: Timer) -> Result<StateMachine<Red>, TransitionError> {
        println!("🚦 Yellow → Red");
        Ok(StateMachine::with_state_data(Duration::from_secs(5)))
    }
}

fn main() {
    println!("=== Traffic Light Controller ===\n");

    let mut traffic_light = StateMachine::<Red>::new()
        .with_state_data(Duration::from_secs(5));

    // Run for 3 cycles
    for cycle in 1..=3 {
        println!("\nCycle {}", cycle);

        // Red → Green
        let duration = traffic_light.state_data();
        println!("⏱️  Red for {:?}", duration);
        thread::sleep(duration);

        traffic_light = traffic_light.transition(Timer)
            .actions(
                actions::ActionBuilder::new()
                    .on_entry(|_| println!("  → Entering Green"))
                    .on_exit(|_| println!("  ← Exiting Green"))
            ).unwrap();

        // Green → Yellow
        let duration = traffic_light.state_data();
        println!("⏱️  Green for {:?}", duration);
        thread::sleep(duration);

        traffic_light = traffic_light.transition(Timer).unwrap();

        // Yellow → Red
        let duration = traffic_light.state_data();
        println!("⏱️  Yellow for {:?}", duration);
        thread::sleep(duration);

        traffic_light = traffic_light.transition(Timer).unwrap();
    }

    println!("\n✅ Traffic light cycles complete");

    // Generate diagram
    traffic_light.write_diagram("traffic-light.puml", DiagramFormat::PlantUML).unwrap();
    println!("✅ Diagram saved to traffic-light.puml");
}
```

**Output**:

```
=== Traffic Light Controller ===

Cycle 1
⏱️  Red for 5s
🚦 Red → Green
  → Entering Green
⏱️  Green for 10s
🚦 Green → Yellow
  ← Exiting Green
⏱️  Yellow for 3s
🚦 Yellow → Red
...
✅ Traffic light cycles complete
✅ Diagram saved to traffic-light.puml
```

---

## Example 3: Order Processing Workflow

**State machine with guards and state data**

```rust
use statemachine::{StateMachine, State, Event, Transitionable, TransitionError, Guard};
use std::collections::HashMap;

// Define states
struct Cart;
struct Checkout;
struct PaymentPending;
struct Paid;
struct Shipped;
struct Delivered;

impl State for Cart {
    type Data = OrderData;
    type Parent = ();
}

impl State for Checkout { type Data = OrderData; type Parent = (); }
impl State for PaymentPending { type Data = OrderData; type Parent = (); }
impl State for Paid { type Data = OrderData; type Parent = (); }
impl State for Shipped { type Data = OrderData; type Parent = (); }
impl State for Delivered { type Data = OrderData; type Parent = (); }

// Define events
struct AddItem {
    product_id: u32,
    quantity: u32,
    price: f64,
}

struct StartCheckout;
struct SubmitPayment {
    amount: f64,
    method: String,
}

struct ShipOrder {
    tracking_number: String,
}

struct MarkDelivered;

impl Event for AddItem {}
impl Event for StartCheckout {}
impl Event for SubmitPayment {}
impl Event for ShipOrder {}
impl Event for MarkDelivered {}

// State data
#[derive(Debug, Clone)]
struct OrderData {
    items: HashMap<u32, (u32, f64)>, // product_id -> (quantity, price)
    total: f64,
    payment_method: Option<String>,
    tracking_number: Option<String>,
}

impl Default for OrderData {
    fn default() -> Self {
        OrderData {
            items: HashMap::new(),
            total: 0.0,
            payment_method: None,
            tracking_number: None,
        }
    }
}

// Guards
struct HasItems;
impl Guard<StartCheckout> for HasItems {
    fn check(&self, event: &StartCheckout) -> bool {
        true // TODO: Check if cart has items
    }
}

struct HasValidPayment;
impl Guard<SubmitPayment> for HasValidPayment {
    fn check(&self, event: &SubmitPayment) -> bool {
        event.amount > 0.0 && !event.method.is_empty()
    }
}

// Define transitions
impl Transitionable<AddItem> for Cart {
    type Next = Cart;

    fn transition(mut self, event: AddItem) -> Result<StateMachine<Cart>, TransitionError> {
        let data = self.state_data_mut();
        let total = event.price * event.quantity as f64;
        data.items.insert(event.product_id, (event.quantity, event.price));
        data.total += total;
        println!("🛒 Added {} × Product ${}", event.quantity, event.product_id);
        println!("   New total: ${:.2}", data.total);
        Ok(self)
    }
}

impl Transitionable<StartCheckout> for Cart {
    type Next = Checkout;

    fn transition(self, _event: StartCheckout) -> Result<StateMachine<Checkout>, TransitionError> {
        println!("🛍️  Starting checkout");
        Ok(StateMachine::with_state_data(self.state_data().clone()))
    }
}

impl Transitionable<SubmitPayment> for Checkout {
    type Next = Paid;

    fn transition(mut self, event: SubmitPayment) -> Result<StateMachine<Paid>, TransitionError> {
        println!("💳 Processing payment of ${:.2}", event.amount);
        let data = self.state_data_mut();
        data.payment_method = Some(event.method);
        Ok(StateMachine::with_state_data(data.clone()))
    }
}

impl Transitionable<ShipOrder> for Paid {
    type Next = Shipped;

    fn transition(mut self, event: ShipOrder) -> Result<StateMachine<Shipped>, TransitionError> {
        println!("📦 Shipping order with tracking: {}", event.tracking_number);
        let data = self.state_data_mut();
        data.tracking_number = Some(event.tracking_number);
        Ok(StateMachine::with_state_data(data.clone()))
    }
}

impl Transitionable<MarkDelivered> for Shipped {
    type Next = Delivered;

    fn transition(self, _event: MarkDelivered) -> Result<StateMachine<Delivered>, TransitionError> {
        println!("✅ Order delivered!");
        Ok(StateMachine::with_state_data(self.state_data().clone()))
    }
}

fn main() {
    println!("=== Order Processing Workflow ===\n");

    // Start with empty cart
    let mut order = StateMachine::<Cart>::new();

    // Add items
    order = order.transition(AddItem {
        product_id: 1,
        quantity: 2,
        price: 29.99,
    }).unwrap();

    order = order.transition(AddItem {
        product_id: 2,
        quantity: 1,
        price: 49.99,
    }).unwrap();

    // Checkout
    order = order.transition(StartCheckout).unwrap();

    // Pay
    order = order.transition(SubmitPayment {
        amount: order.state_data().total,
        method: "credit_card".to_string(),
    }).unwrap();

    // Ship
    order = order.transition(ShipOrder {
        tracking_number: "1Z999AA10123456784".to_string(),
    }).unwrap();

    // Deliver
    order = order.transition(MarkDelivered).unwrap();

    println!("\n✅ Order complete!");
    println!("Final state: {}", order.state_name());
    println!("Total: ${:.2}", order.state_data().total);
    println!("Tracking: {}", order.state_data().tracking_number.as_ref().unwrap());

    // Generate diagram
    order.write_diagram("order-processing.puml", DiagramFormat::PlantUML).unwrap();
    println!("\n✅ Diagram saved to order-processing.puml");
}
