## Example 4: Authentication Flow

**State machine with guards and error handling**

```rust
use statemachine::{StateMachine, State, Event, Transitionable, TransitionError, Guard};

// Define states
struct Anonymous;
struct CredentialsSubmitted;
struct MFARequired;
struct Authenticated;
struct AuthFailed;
struct Locked;

impl State for Anonymous { type Data = AuthData; type Parent = (); }
impl State for CredentialsSubmitted { type Data = AuthData; type Parent = (); }
impl State for MFARequired { type Data = AuthData; type Parent = (); }
impl State for Authenticated { type Data = AuthData; type Parent = (); }
impl State for AuthFailed { type Data = AuthData; type Parent = (); }
impl State for Locked { type Data = AuthData; type Parent = (); }

// Define events
struct SubmitCredentials {
    username: String,
    password: String,
}

struct SubmitMFA {
    code: String,
}

struct LoginSuccess;
struct LoginFailed;
struct LockAccount;

impl Event for SubmitCredentials {}
impl Event for SubmitMFA {}
impl Event for LoginSuccess {}
impl Event for LoginFailed {}
impl Event for LockAccount {}

// State data
#[derive(Debug, Clone, Default)]
struct AuthData {
    username: Option<String>,
    failed_attempts: u32,
    lockout_until: Option<std::time::SystemTime>,
}

// Guards
struct IsValidPassword;
impl Guard<SubmitCredentials> for IsValidPassword {
    fn check(&self, event: &SubmitCredentials) -> bool {
        !event.username.is_empty() && event.password.len() >= 8
    }
}

struct IsNotLocked;
impl Guard<SubmitCredentials> for IsNotLocked {
    fn check(&self, event: &SubmitCredentials) -> bool {
        true // TODO: Check if account is locked
    }
}

struct HasValidMFA;
impl Guard<SubmitMFA> for HasValidMFA {
    fn check(&self, event: &SubmitMFA) -> bool {
        event.code.len() == 6 && event.code.chars().all(|c| c.is_ascii_digit())
    }
}

// Define transitions
impl Transitionable<SubmitCredentials> for Anonymous {
    type Next = CredentialsSubmitted;

    fn transition(mut self, event: SubmitCredentials) -> Result<StateMachine<CredentialsSubmitted>, TransitionError> {
        println!("🔐 Credentials submitted for: {}", event.username);
        let data = self.state_data_mut();
        data.username = Some(event.username);
        Ok(StateMachine::with_state_data(data.clone()))
    }
}

impl Transitionable<SubmitMFA> for MFARequired {
    type Next = Authenticated;

    fn transition(self, event: SubmitMFA) -> Result<StateMachine<Authenticated>, TransitionError> {
        println!("✅ MFA verified: {}", event.code);
        Ok(StateMachine::with_state_data(self.state_data().clone()))
    }
}

impl Transitionable<LoginFailed> for CredentialsSubmitted {
    type Next = AuthFailed;

    fn transition(mut self, _event: LoginFailed) -> Result<StateMachine<AuthFailed>, TransitionError> {
        let data = self.state_data_mut();
        data.failed_attempts += 1;
        println!("❌ Login failed (attempt {}/3)", data.failed_attempts);

        if data.failed_attempts >= 3 {
            println!("🔒 Account locked after 3 failed attempts");
            return Ok(StateMachine::with_state_data(data.clone()).into());
        }

        Ok(StateMachine::with_state_data(data.clone()))
    }
}

fn main() {
    println!("=== Authentication Flow ===\n");

    // Simulate login flow
    let mut auth = StateMachine::<Anonymous>::new();

    // Submit credentials
    let result = auth.transition(SubmitCredentials {
        username: "alice".to_string(),
        password: "password123".to_string(),
    });

    match result {
        Ok(machine) => {
            auth = machine;
            println!("✅ Credentials accepted\n");

            // Require MFA
            auth = StateMachine::<MFARequired>::new()
                .with_state_data(auth.state_data().clone());

            // Submit MFA
            let result = auth.transition(SubmitMFA {
                code: "123456".to_string(),
            });

            match result {
                Ok(machine) => {
                    println!("✅ Fully authenticated!");
                    println!("Welcome, {}!", machine.state_data().username.as_ref().unwrap());
                }
                Err(e) => println!("❌ MFA failed: {}", e),
            }
        }
        Err(TransitionError::GuardFailed { guard }) => {
            println!("❌ Guard failed: {}", guard);
        }
        Err(e) => println!("❌ Error: {}", e),
    }

    println!("\n✅ Authentication flow complete");
}
```

**Output**:

```
=== Authentication Flow ===

🔐 Credentials submitted for: alice
✅ Credentials accepted

✅ MFA verified: 123456
✅ Fully authenticated!
Welcome, alice!

✅ Authentication flow complete
```

