## Example 5: Hierarchical State Machine (Document Lifecycle)

**Nested states with parent-child relationships**

```rust
use statemachine::{StateMachine, State, Event, Transitionable, TransitionError};

// Top-level state
struct Document;

// Document substates
struct Draft;
struct UnderReview;
struct Published;

// Published substates (hierarchical!)
struct PublishedDraft;    // Published, but editable
struct PublishedReview;   // Published, under review
struct PublishedLive;     // Published, live to public

impl State for Draft { type Data = (); type Parent = Document; }
impl State for UnderReview { type Data = (); type Parent = Document; }
impl State for Published { type Data = (); type Parent = Document; }

impl State for PublishedDraft {
    type Data = ();
    type Parent = Published; // Parent is Published!
}

impl State for PublishedReview {
    type Data = ();
    type Parent = Published; // Parent is Published!
}

impl State for PublishedLive {
    type Data = ();
    type Parent = Published; // Parent is Published!
}

// Events
struct SubmitForReview;
struct Approve;
struct Publish;
struct EditPublished;
struct RequestReview;
struct GoLive;

impl Event for SubmitForReview {}
impl Event for Approve {}
impl Event for Publish {}
impl Event for EditPublished {}
impl Event for RequestReview {}
impl Event for GoLive {}

// Transitions
impl Transitionable<SubmitForReview> for Draft {
    type Next = UnderReview;
    fn transition(self, _event: SubmitForReview) -> Result<StateMachine<UnderReview>, TransitionError> {
        println!("📝 Draft → Under Review");
        Ok(StateMachine::new())
    }
}

impl Transitionable<Approve> for UnderReview {
    type Next = Published;
    fn transition(self, _event: Approve) -> Result<StateMachine<Published>, TransitionError> {
        println!("✅ Under Review → Published");
        Ok(StateMachine::new())
    }
}

impl Transitionable<EditPublished> for Published {
    type Next = PublishedDraft;
    fn transition(self, _event: EditPublished) -> Result<StateMachine<PublishedDraft>, TransitionError> {
        println!("✏️  Published → Published Draft");
        Ok(StateMachine::new())
    }
}

impl Transitionable<RequestReview> for PublishedDraft {
    type Next = PublishedReview;
    fn transition(self, _event: RequestReview) -> Result<StateMachine<PublishedReview>, TransitionError> {
        println!("👀 Published Draft → Published Review");
        Ok(StateMachine::new())
    }
}

impl Transitionable<GoLive> for PublishedReview {
    type Next = PublishedLive;
    fn transition(self, _event: GoLive) -> Result<StateMachine<PublishedLive>, TransitionError> {
        println!("🚀 Published Review → Published Live");
        Ok(StateMachine::new())
    }
}

fn main() {
    println!("=== Document Lifecycle (Hierarchical) ===\n");

    // Start with draft
    let mut doc = StateMachine::<Draft>::new();
    println!("State path: {:?}\n", doc.state_path());

    // Submit for review
    doc = doc.transition(SubmitForReview).unwrap();
    println!("State path: {:?}\n", doc.state_path());

    // Approve
    doc = doc.transition(Approve).unwrap();
    println!("State path: {:?}\n", doc.state_path());

    // Enter published substate
    doc = doc.transition(EditPublished).unwrap();
    println!("State path: {:?}\n", doc.state_path());

    // Request review within published
    doc = doc.transition(RequestReview).unwrap();
    println!("State path: {:?}\n", doc.state_path());

    // Go live
    doc = doc.transition(GoLive).unwrap();
    println!("State path: {:?}\n", doc.state_path());

    // Generate diagram
    doc.write_diagram("document-lifecycle.puml", DiagramFormat::PlantUML).unwrap();
    println!("✅ Diagram saved to document-lifecycle.puml");
}
```

**Output**:

```
=== Document Lifecycle (Hierarchical) ===

State path: ["Document", "Draft"]

📝 Draft → Under Review
State path: ["Document", "UnderReview"]

✅ Under Review → Published
State path: ["Document", "Published"]

✏️  Published → Published Draft
State path: ["Document", "Published", "PublishedDraft"]

👀 Published Draft → Published Review
State path: ["Document", "Published", "PublishedReview"]

🚀 Published Review → Published Live
State path: ["Document", "Published", "PublishedLive"]

✅ Diagram saved to document-lifecycle.puml
```

