## Example 6: Parallel Regions (Vending Machine)

**Multiple concurrent state machines**

```rust
use statemachine::{ParallelStateMachine, State, Event, Transitionable, TransitionError};

// Region 1: Money handling
struct MoneyIdle;
struct MoneyInserted;
struct MoneyProcessing;
struct MoneyChangeDue;

impl State for MoneyIdle { type Data = MoneyData; type Parent = (); }
impl State for MoneyInserted { type Data = MoneyData; type Parent = (); }
impl State for MoneyProcessing { type Data = MoneyData; type Parent = (); }
impl State for MoneyChangeDue { type Data = MoneyData; type Parent = (); }

// Region 2: Product selection
struct SelectionIdle;
struct SelectionMade;
struct SelectionDispensing;
struct SelectionComplete;

impl State for SelectionIdle { type Data = SelectionData; type Parent = (); }
impl State for SelectionMade { type Data = SelectionData; type Parent = (); }
impl State for SelectionDispensing { type Data = SelectionData; type Parent = (); }
impl State for SelectionComplete { type Data = SelectionData; type Parent = (); }

// State data
#[derive(Debug, Clone, Default)]
struct MoneyData {
    inserted: u32,
    required: u32,
    change: u32,
}

#[derive(Debug, Clone, Default)]
struct SelectionData {
    product_id: Option<u32>,
    product_name: Option<String>,
    price: u32,
}

// Events for Region 1 (Money)
struct InsertCoin {
    amount: u32,
}

struct ReturnChange;

// Events for Region 2 (Selection)
struct SelectProduct {
    product_id: u32,
    name: String,
    price: u32,
}

struct DispenseProduct;

impl Event for InsertCoin {}
impl Event for ReturnChange {}
impl Event for SelectProduct {}
impl Event for DispenseProduct {}

// Transitions for Region 1
impl Transitionable<InsertCoin> for MoneyIdle {
    type Next = MoneyInserted;
    fn transition(self, event: InsertCoin) -> Result<StateMachine<MoneyInserted>, TransitionError> {
        println!("💰 Inserted ${}", event.amount);
        Ok(StateMachine::with_state_data(MoneyData {
            inserted: event.amount,
            required: 0,
            change: 0,
        }))
    }
}

// Transitions for Region 2
impl Transitionable<SelectProduct> for SelectionIdle {
    type Next = SelectionMade;
    fn transition(self, event: SelectProduct) -> Result<StateMachine<SelectionMade>, TransitionError> {
        println!("🛒 Selected: {} (${})", event.name, event.price);
        Ok(StateMachine::with_state_data(SelectionData {
            product_id: Some(event.product_id),
            product_name: Some(event.name),
            price: event.price,
        }))
    }
}

fn main() {
    println!("=== Vending Machine (Parallel Regions) ===\n");

    // Create parallel state machine
    let mut vending = ParallelStateMachine::<MoneyIdle, SelectionIdle>::new()
        .with_region1_data(MoneyData::default())
        .with_region2_data(SelectionData::default())
        .unwrap();

    println!("Region 1 (Money): {:?}", vending.region1_state_name());
    println!("Region 2 (Selection): {:?}\n", vending.region2_state_name());

    // Insert money (Region 1)
    vending = vending.transition_region1(InsertCoin { amount: 150 }).unwrap();
    println!("Region 1 (Money): {:?}", vending.region1_state_name());
    println!("Region 2 (Selection): {:?}\n", vending.region2_state_name());

    // Select product (Region 2)
    vending = vending.transition_region2(SelectProduct {
        product_id: 1,
        name: "Soda".to_string(),
        price: 100,
    }).unwrap();
    println!("Region 1 (Money): {:?}", vending.region1_state_name());
    println!("Region 2 (Selection): {:?}\n", vending.region2_state_name());

    // Synchronize both regions
    vending = vending.synchronize().unwrap();
    println!("✅ Both regions synchronized");

    // Query both regions
    let money = vending.region1_data();
    let selection = vending.region2_data();
    println!("Money inserted: ${}", money.inserted);
    println!("Product: {}", selection.product_name.as_ref().unwrap());
    println!("Change due: ${}", money.inserted - selection.price);

    println!("\n✅ Vending transaction complete");
}
```

**Output**:

```
=== Vending Machine (Parallel Regions) ===

Region 1 (Money): "MoneyIdle"
Region 2 (Selection): "SelectionIdle"

💰 Inserted $150
Region 1 (Money): "MoneyInserted"
Region 2 (Selection): "SelectionIdle"

🛒 Selected: Soda ($100)
Region 1 (Money): "MoneyInserted"
Region 2 (Selection): "SelectionMade"

✅ Both regions synchronized
Money inserted: $150
Product: Soda
Change due: $50

✅ Vending transaction complete
```

