    let start_memory = get_memory_usage();

    let result = process_large_dataset();

    let end_memory = get_memory_usage();
    let memory_used = end_memory - start_memory;

    expect(memory_used).to_be_less_than(100 * 1024 * 1024); // 100MB
}
```

### Performance Regression Tests

```rust
#[test]
fn test_performance_regression() {
    let baseline = load_baseline("sorting_baseline.json");

    let data = generate_test_data(10000);
    let duration = measure_time(|| sort(data));

    expect(duration).to_be_close_to(baseline.duration, 0.1); // Within 10%
}
```

### Load Testing

```rust
#[test]
#[tag("load-test")]
async fn test_concurrent_requests() {
    let server = TestServer::start().await;

    let handles: Vec<_> = (0..100)
        .map(|_| {
            let server = server.clone();
            tokio::spawn(async move {
                server.get("/api/users").await
            })
        })
        .collect();

    let results = futures::future::join_all(handles).await;

    expect(results.iter().filter(|r| r.is_ok())).to_have_count(100);
}
