## Common Patterns

### Metrics Storage

**Prometheus-style Metrics**:
```rust
use metrics::{counter, gauge, histogram};
use metrics_exporters_timeseries::TimeseriesRecorder;

let db = Database::open("/data/metrics").await?;
let recorder = TimeseriesRecorder::new(db);
metrics::set_boxed_recorder(Box::new(recorder));

// Metrics automatically stored
counter!("requests_total", 1);
gauge!("cpu_usage", 75.5);
histogram!("latency_ms", 125.0);

// Query metrics
let points = db.query(
    Query::from("requests_total")
        .range(start..end)
        .aggregate(Aggregate::Rate)
).await?;
```

### IoT Sensor Data

**Sensor Reading Loop**:
```rust
use tokio::time::{interval, Duration};

let mut ticker = interval(Duration::from_secs(1));
loop {
    ticker.tick().await;

    // Read from sensor
    let temp = read_temperature_sensor()?;
    let humidity = read_humidity_sensor()?;

    // Write to database
    db.write(Point::new("temperature")
        .tag("location", "greenhouse")
        .tag("sensor", "sensor-1")
        .field("value", temp)
    ).await?;

    db.write(Point::new("humidity")
        .tag("location", "greenhouse")
        .tag("sensor", "sensor-1")
        .field("value", humidity)
    ).await?;
}
```

### Application Monitoring

**HTTP Request Tracking**:
```rust
use axum::{extract::Request, middleware::Next, response::Response};

async fn request_tracker(
    req: Request,
    next: Next,
) -> Response {
    let start = SystemTime::now();
    let method = req.method().to_string();
    let path = req.uri().path().to_string();

    let response = next.run(req).await;

    let duration = start.elapsed().unwrap().as_millis() as f64;
    let status = response.status().as_u16();

    db.write(Point::new("http_request")
        .tag("method", method)
        .tag("path", path)
        .tag("status", status.to_string())
        .field("duration_ms", duration)
        .field("success", status < 400)
    ).await?;

    response
}
```

**Query Error Rate**:
```rust
let points = db.query(
    Query::from("http_request")
        .range(start..end)
        .filter_regex("status", r"[45]\d\d")
        .aggregate(Aggregate::Rate)
).await?;
```

### Financial Data

**Stock Price Storage**:
```rust
db.write(Point::new("stock_price")
    .tag("symbol", "AAPL")
    .field("price", 175.43)
    .field("volume", 45_000_000)
    .timestamp(timestamp)
).await?;
```

**Query Candlestick Data**:
```rust
let points = db.query(
    Query::from("stock_price")
        .filter("symbol", "AAPL")
        .range(start..end)
        .group_by(vec![])
        .window(Duration::from_secs(86400))  // 1-day candles
).await?;

// Custom aggregation for OHLC
let ohlc = calculate_ohlc(points)?;
```

### Anomaly Detection

**Threshold Alerting**:
```rust
let points = db.query(
    Query::from("temperature")
        .range(start..end)
        .aggregate(Aggregate::Max)
).await?;

if let Some(FieldValue::Float(temp)) = points[0].field("max") {
    if temp > 30.0 {
        send_alert("Temperature too high!")?;
    }
}
```

**Continuous Queries**:
```rust
db.create_continuous_query(
    "alert_high_temp",
    Query::from("temperature")
        .range(now() - Duration::from_secs(300)..now())
        .aggregate(Aggregate::Max)
        .having("value", "> 30"),
    Interval::from_secs(60),
    |points| {
        if !points.is_empty() {
            alert!("High temperature detected: {:?}", points);
        }
    }
).await?;
```

