### Database Module (src/database.rs)

```rust
use crate::storage::{WAL, Cache, TSMManager, Index};
use crate::query::QueryExecutor;

pub struct Database {
    path: PathBuf,
    wal: WAL,
    cache: Cache,
    tsm: TSMManager,
    index: Index,
    executor: QueryExecutor,
    config: DatabaseConfig,
}

impl Database {
    /// Open database at path
    pub async fn open(path: impl Into<PathBuf>) -> Result<Self, Error> {
        let path = path.into();
        let config = DatabaseConfig::default();

        // Create directories
        tokio::fs::create_dir_all(&path).await?;

        // Initialize components
        let wal = WAL::open(path.join("wal")).await?;
        let cache = Cache::new(config.write_buffer_size);
        let tsm = TSMManager::open(path.join("data")).await?;
        let index = Index::load_or_create(path.join("index")).await?;
        let executor = QueryExecutor::new(tsm.clone(), index.clone());

        // Replay WAL
        let mut replay = wal.replay()?;
        while let Some(point) = replay.next().await? {
            cache.insert(point)?;
        }

        Ok(Self {
            path,
            wal,
            cache,
            tsm,
            index,
            executor,
            config,
        })
    }

    /// Write point to database
    pub async fn write(&self, point: Point) -> Result<(), Error> {
        // 1. Write to WAL (durability)
        self.wal.append(&point).await?;

        // 2. Insert into cache
        self.cache.insert(point.clone())?;

        // 3. Check if flush needed
        if self.cache.should_flush() {
            self.flush().await?;
        }

        Ok(())
    }

    /// Query database
    pub async fn query(&self, query: Query) -> Result<Vec<Point>, Error> {
        self.executor.execute(query).await
    }

    /// Flush cache to TSM files
    pub async fn flush(&self) -> Result<(), Error> {
        let points = self.cache.drain();

        // Group by series key
        let mut series_points: HashMap<SeriesKey, Vec<Point>> = HashMap::new();
        for point in points {
            series_points.entry(point.series_key()).or_default().push(point);
        }

        // Write each series to TSM
        for (series_key, mut points) in series_points {
            points.sort_by_key(|p| p.timestamp());
            self.tsm.write_series(&series_key, &points).await?;
            self.index.update_series(&series_key).await?;
        }

        // Clear WAL
        self.wal.rotate().await?;

        Ok(())
    }
}
```

