## Testing Guide

### Unit Tests

**Test Organization**:
```rust
// src/compression/gorilla.rs
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_encode_decode_single_value() {
        let values = vec![22.5];
        let encoded = GorillaEncoder::encode(&values);
        let decoded = GorillaDecoder::decode(&encoded);
        assert_eq!(values, decoded);
    }

    #[test]
    fn test_encode_decode_repeated_values() {
        let values = vec![22.5, 22.5, 22.5, 22.5];
        let encoded = GorillaEncoder::encode(&values);
        let decoded = GorillaDecoder::decode(&encoded);
        assert_eq!(values, decoded);
        assert!(encoded.len() < values.len() * 8); // Compressed
    }

    #[test]
    fn test_compression_ratio() {
        let values: Vec<f64> = (0..1000).map(|i| 22.5 + i as f64 * 0.1).collect();
        let encoded = GorillaEncoder::encode(&values);
        let ratio = (values.len() * 8) as f64 / encoded.len() as f64;
        assert!(ratio > 2.0, "Compression ratio should be > 2x, got {}", ratio);
    }
}
