    ui.input(&mut state.name, "Name")
        .validate(|s| !s.is_empty());

    ui.input(&mut state.email, "Email")
        .validate(|s| s.contains('@'));

    ui.checkbox("Accept terms", &mut state.agreed);

    ui.button("Submit", || {
        submit_form(state);
    }).disabled(!state.agreed);
})
```

