```rust
#[tokio::main]
async fn main() -> Result<()> {
    tui::run_async(|ui| async move {
        ui.button("Load Data", || async {
            let data = fetch_data().await?;
            ui.update_state(data);
            Ok(())
        });
    }).await
}
```

### Data Table

```rust
ui.table(users, |ui, user| {
    ui.cell(&user.id);
    ui.cell(&user.name);
    ui.cell(&user.email);
})
    .headers(["ID", "Name", "Email"])
