```rust
ui.scroll(|ui| {
    for log in logs {
        let style = match log.level {
            LogLevel::Error => fg(Red) + bold,
            LogLevel::Warning => fg(Yellow),
            _ => fg(White),
        };

        ui.label(format!("[{}] {}", log.time, log.message))
