## Recovery Strategies

### 1. Log-Based Recovery

**Strategy**: Scan transaction log for incomplete transactions

**Implementation**:
```rust
pub struct LogBasedRecovery {
    logger: Arc<dyn TransactionLogger>,
    coordinator: Arc<Coordinator>,
}

impl LogBasedRecovery {
    pub async fn recover(&self) -> Result<RecoveryReport> {
        // Find incomplete transactions
        let incomplete = self.logger.find_incomplete_transactions()?;

        let mut report = RecoveryReport::new();

        for tx_id in incomplete {
            let tx = self.logger.get_transaction(tx_id)?;

            // Decide recovery action based on state
            match tx.state {
                TransactionState::Prepared => {
                    if tx.is_expired() {
                        self.rollback_transaction(tx).await?;
                        report.rolled_back.push(tx.id);
                    }
                }
                TransactionState::Committing => {
                    self.commit_transaction(tx).await?;
                    report.committed.push(tx.id);
                }
                TransactionState::RollingBack => {
                    self.force_rollback(tx).await?;
                    report.rolled_back.push(tx.id);
                }
                _ => {}
            }
        }

        Ok(report)
    }
}
```

### 2. Timeout-Based Recovery

**Strategy**: Rollback transactions that have exceeded timeout

**Implementation**:
```rust
pub struct TimeoutBasedRecovery {
    logger: Arc<dyn TransactionLogger>,
    timeout: Duration,
}

impl TimeoutBasedRecovery {
    pub async fn recover(&self) -> Result<RecoveryReport> {
        let expired = self.logger.find_expired_transactions(self.timeout)?;

        let mut report = RecoveryReport::new();

        for tx_id in expired {
            let tx = self.logger.get_transaction(tx_id)?;
            self.rollback_transaction(tx).await?;
            report.rolled_back.push(tx.id);
        }

        Ok(report)
    }
}
```

### 3. Participant-Based Recovery

**Strategy**: Recover failed participants

**Implementation**:
```rust
pub struct ParticipantRecovery {
    registry: Arc<ParticipantRegistry>,
    health_checker: Arc<HealthChecker>,
}

impl ParticipantRecovery {
    pub async fn recover_participant(
        &self,
        participant_id: ParticipantId
    ) -> Result<()> {
        // Check participant health
        let health = self.health_checker.check(participant_id).await?;

        if health == HealthStatus::Unhealthy {
            // Find active transactions
            let transactions = self.registry.get_transactions_for_participant(participant_id)?;

            // Compensate all active transactions
            for tx_id in transactions {
                self.compensate_transaction(tx_id).await?;
            }

            // Restart participant
            self.registry.restart_participant(participant_id).await?;
        }

        Ok(())
    }
}
```

### 4. Snapshot-Based Recovery

**Strategy**: Periodically snapshot transaction state, recover from snapshot

**Implementation**:
```rust
pub struct SnapshotRecovery {
    snapshot_store: Arc<SnapshotStore>,
    interval: Duration,
}

impl SnapshotRecovery {
    pub async fn create_snapshot(&self, tx: &Transaction) -> Result<()> {
        let snapshot = TransactionSnapshot {
            id: tx.id.clone(),
            state: tx.state.clone(),
            completed_steps: tx.completed_steps.clone(),
            timestamp: Utc::now(),
        };

        self.snapshot_store.save(snapshot).await?;
        Ok(())
    }

    pub async fn recover_from_snapshot(&self, tx_id: TxId) -> Result<Transaction> {
        let snapshot = self.snapshot_store.get(tx_id).await?;

        // Restore transaction from snapshot
        let tx = Transaction::from_snapshot(snapshot)?;

        Ok(tx)
    }
}
```

