        let mut test = TransactionTest::new();

        // Add failing step
        test.add_step(MockStep::success("step1"));
        test.add_step(MockStep::failure("step2", Error::StepFailed));

        // Execute transaction
        let result = test.execute(|| {
            transaction! {
                step1()?;
                step2()?;
            }
        }).await;

        // Verify rollback
        assert!(result.is_err());
        assert_eq!(test.get_transaction_state(), TransactionState::RolledBack);
        assert!(test.step_executed("step1"));
        assert!(test.step_executed("step2"));
    }
}
