### Host Function with Return Value

```rust
instance.register_host_function("get_time", || -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_millis() as i64
})?;
```

### Host Function with Memory Access

```rust
use wasmer_rs::{Wasmer, Instance};

fn register_complex_host_function(instance: &mut Instance) -> Result<(), Box<dyn std::error::Error>> {
    let memory = instance.memory("memory")?.clone_for_async();

    instance.register_host_function("process_string", |ptr: i32, len: i32| -> i32 {
        // Read string from WASM memory
        let mut buffer = vec![0u8; len as usize];
        memory.copy_to_host(ptr as usize, &mut buffer)?;
        let input = String::from_utf8(buffer)?;

        // Process string
        let output = format!("Processed: {}", input);

        // Write result back to WASM memory
        let result_ptr = 1000;
        memory.write_slice(result_ptr, output.as_bytes())?;

        Ok(result_ptr as i32)
    })?;

    Ok(())
}
```

### Host Function with State

```rust
use wasmer_rs::Wasmer;
use std::sync::Arc;

struct Database {
    // ... database fields
}

impl Database {
    fn new() -> Self {
        // Initialize database
        Self {}
    }

    fn query(&self, sql: &str) -> Result<Vec<String>> {
        // Execute query
        Ok(vec!["result1".to_string(), "result2".to_string()])
    }
}

fn register_stateful_host_function(
    instance: &mut Instance,
    db: Arc<Database>,
) -> Result<(), Box<dyn std::error::Error>> {
    let memory = instance.memory("memory")?.clone_for_async();

    instance.register_host_function("db_query", move |sql_ptr: i32, sql_len: i32| -> i32 {
        // Read SQL from WASM memory
        let mut buffer = vec![0u8; sql_len as usize];
        memory.copy_to_host(sql_ptr as usize, &mut buffer)?;
        let sql = String::from_utf8(buffer)?;

        // Execute query
        let results = db.query(&sql)?;

        // Write results back
        let results_json = serde_json::to_string(&results)?;
        let result_ptr = 2000;
        memory.write_slice(result_ptr, results_json.as_bytes())?;

        Ok(result_ptr as i32)
    })?;

    Ok(())
}

// Usage
let mut instance = Wasmer::load("module.wasm")?;
let db = Arc::new(Database::new());
register_stateful_host_function(&mut instance, db)?;
```

### Async Host Function

```rust
use wasmer_rs::Wasmer;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut instance = Wasmer::load("module.wasm")?;

    // Register async host function (uses runtime)
    instance.register_host_function("fetch", |url_ptr: i32, url_len: i32| -> i32 {
        // Read URL from WASM memory
        let memory = instance.memory("memory")?;
        let mut buffer = vec![0u8; url_len as usize];
        memory.copy_to_host(url_ptr as usize, &mut buffer)?;
        let url = String::from_utf8(buffer)?;

        // Fetch URL asynchronously
        let response = tokio::task::block_in_place(|| {
            tokio::runtime::Handle::current().block_on(async {
                reqwest::get(&url).await?.text().await
            })
        })?;

        // Write response back to WASM memory
        let result_ptr = 3000;
        memory.write_slice(result_ptr, response.as_bytes())?;

        Ok(result_ptr as i32)
    })?;

    Ok(())
}
```

