    use wasmer_rs::Wasmer;

    #[test]
    fn test_add_function() {
        let instance = Wasmer::load("module.wasm").unwrap();
        let result: i32 = instance.call("add", (1, 2)).unwrap();
        assert_eq!(result, 3);
    }

    #[test]
    fn test_memory_operations() {
        let instance = Wasmer::load("module.wasm").unwrap();
        let memory = instance.memory("memory").unwrap();

        memory.write(0, 42i32).unwrap();
        let value: i32 = memory.read(0).unwrap();
        assert_eq!(value, 42);
    }
}
```

### Integration Tests

**Create test WASM modules**:

```bash
tests/
├── fixtures/
│   ├── simple.wasm
│   ├── memory.wasm
│   └── host_functions.wasm
└── integration_tests.rs
```

**Integration test**:

```rust
#[test]
fn test_host_function_integration() {
    let mut instance = Wasmer::load("tests/fixtures/host_functions.wasm").unwrap();

    instance.register_host_function("add", |a: i32, b: i32| -> i32 {
        a + b
    }).unwrap();

    let result: i32 = instance.call("call_add", (10, 20)).unwrap();
    assert_eq!(result, 30);
}
```

### Property-Based Testing

```rust
use proptest::prelude::*;

proptest! {
    #[test]
    fn test_add_properties(a in any::<i32>(), b in any::<i32>()) {
        let instance = Wasmer::load("module.wasm").unwrap();
        let result: i32 = instance.call("add", (a, b)).unwrap();

        // Test commutativity
        let result2: i32 = instance.call("add", (b, a)).unwrap();
        assert_eq!(result, result2);

        // Test identity
        let zero: i32 = instance.call("add", (a, 0)).unwrap();
        assert_eq!(zero, a);
    }
}
```

### Fuzzing

**Install AFL**:

```bash
cargo install afl
```

**Fuzz target**:

```rust
#![no_main]

use libfuzzer_sys::fuzz_target;
use wasmer_rs::Wasmer;

fuzz_target!(|data: &[u8]| {
    if let Ok(instance) = Wasmer::load_bytes(data) {
        let _ = instance.call::<(), ()>("test", ());
    }
});
```

**Run fuzzer**:

```bash
cargo fuzz run fuzz_target
```

