## Edge Cases

### Symlink Cycles

```rust
impl Watcher {
    fn follow_symlink_safe(&self, path: &Path) -> Result<PathBuf> {
        let mut visited = HashSet::new();
        let mut current = path.to_path_buf();

        loop {
            if !current.is_symlink() {
                return Ok(current);
            }

            if visited.contains(&current) {
                return Err(Error::SymlinkCycle);
            }

            visited.insert(current.clone());

            match current.read_link() {
                Ok(target) => current = target,
                Err(e) => return Err(Error::Io(e)),
            }
        }
    }
}
```

### Race Conditions

```rust
// File deleted between event and handler
watcher.on_change(|event| {
    match std::fs::metadata(&event.path) {
        Ok(_) => {
            // File still exists
            process(&event.path);
        }
        Err(_) => {
            // File was deleted, handle gracefully
            eprintln!("File disappeared: {:?}", event.path);
        }
    }
})?;
```

### Editor Temp Files

```rust
impl SmartDebouncer {
    fn is_temp_file(&self, path: &Path) -> bool {
        let name = path.file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("");

        // Vim
        if name.ends_with(".swp") || name.ends_with(".swo") {
            return true;
        }

        // Emacs
        if name.starts_with(".#") || name.ends_with("~") {
            return true;
        }

        // VSCode
        if name.starts_with(".~") {
            return true;
        }

        // Generic
        name.starts_with('.') || name.starts_with('~')
    }
}
```

### High Event Rates

```rust
// Use backpressure
watcher.on_change(|event| {
    let semaphore = Arc::clone(&handler_semaphore);
    tokio::spawn(async move {
        let _permit = semaphore.acquire().await.unwrap();
        process(event);
    });
})?;
```

