### Use Case: Event-Driven Architecture

Build event-driven systems with file changes as event sources:

```rust
use watcher_rs::Watcher;
use eventstream_rs::{Producer, Consumer};

#[tokio::main]
async fn main() -> watcher_rs::Result<()> {
    // Producer: Watch files and publish events
    let producer = Producer::new("file-changes")?;

    Watcher::new("data/")?
        .on_change_async(move |event| {
            let producer = producer.clone();
            async move {
                producer.publish(event).await?;
                Ok(())
            }
        })?
        .await?;

    // Consumer: Process file events
    let mut consumer = Consumer::new("file-changes")?.subscribe()?;

    while let Some(event) = consumer.next().await {
        match event.kind {
            EventKind::Create => process_new_file(&event.path),
            EventKind::Modify => process_modified_file(&event.path),
            EventKind::Remove => process_deleted_file(&event.path),
            _ => {}
        }
    }

    Ok(())
}
```

