backend websocket_servers
    balance source
    server server1 10.0.0.1:8080 check
    server server2 10.0.0.2:8080 check
    server server3 10.0.0.3:8080 check
```

### State Synchronization

**Using Redis**:

```rust
use redis::AsyncCommands;

#[derive(Serialize, Deserialize)]
struct ConnectionState {
    user_id: String,
    rooms: Vec<String>,
    metadata: HashMap<String, String>,
}

async fn sync_state_to_redis(conn: &Connection, state: &ConnectionState) -> Result<()> {
    let mut redis = redis::Client::open("redis://localhost")?.get_async_connection().await?;

    // Save connection state
    let key = format!("conn:{}", conn.id());
    let value = serde_json::to_string(state)?;
    redis.set(key, value).await?;

    // Add to user's connection set
    let user_key = format!("user:{}", state.user_id);
    redis.sadd(user_key, conn.id()).await?;

    Ok(())
}
```

