## Connection Lifecycle Management

### Connection States

```
Connecting → Connected → Disconnecting → Disconnected
    ↑                                           ↓
    └──────────────── Reconnecting ─────────────┘
```

### State Transitions

```rust
async fn handle_connection(stream: TcpStream, server: &WebSocketServer) -> Result<()> {
    // 1. Connecting
    let ws_stream = accept_async(stream).await?;
    let mut conn = Connection::new(ws_stream);

    // 2. Connected
    server.on_connect_hook.call(&conn)?;
    server.connections.register(conn.clone()).await?;

    // 3. Message loop
    loop {
        match conn.next().await {
            Some(Ok(msg)) => {
                server.handle_message(msg, conn).await?;
            },
            Some(Err(e)) => {
                // Error → Disconnecting
                break;
            },
            None => {
                // Closed → Disconnecting
                break;
            },
        }
    }

    // 4. Disconnecting
    server.connections.unregister(conn.id()).await?;
    server.on_disconnect_hook.call(conn)?;

    // 5. Disconnected
    Ok(())
}
```

### Graceful Shutdown

```rust
use tokio::signal;

#[tokio::main]
async fn main() -> Result<()> {
    let server = WebSocketServer::new();

    // Setup signal handling
    let ctrl_c = async {
        signal::ctrl_c().await?;
        Ok::<(), Error>(())
    };

    #[cfg(unix)]
    let terminate = async {
        signal::unix::signal(signal::unix::SignalKind::terminate())?
            .recv().await;
        Ok::<(), Error>(())
    };

    // Run server until shutdown signal
    server.listen_with_shutdown("0.0.0.0:8080", ctrl_c).await?;

    Ok(())
}
```

### Connection Cleanup

```rust
async fn cleanup_connection(conn_id: ConnectionId, server: &WebSocketServer) -> Result<()> {
    // Remove from all rooms
    let rooms = server.list_rooms().await;
    for room_name in rooms {
        let room = server.room(&room_name);
        if room.members().await.contains(&conn_id) {
            room.leave(conn_id).await?;
        }
    }

    // Remove subscriptions
    server.unsubscribe_all(conn_id).await;

    // Notify other systems
    notify_disconnection(conn_id).await?;

    Ok(())
}
```

