## Example 2: Chat Room with Multiple Clients

Multi-room chat server with user management.

### examples/chat_room.rs

```rust
use serde::{Deserialize, Serialize};
use websocket_rs::WebSocketServer;
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;

#[derive(Serialize, Deserialize, Clone)]
struct ChatMessage {
    room: String,
    user: String,
    text: String,
    timestamp: i64,
}

#[derive(Serialize, Deserialize)]
#[serde(tag = "type")]
enum ClientMessage {
    #[serde(rename = "join")]
    Join { room: String, username: String },

    #[serde(rename = "leave")]
    Leave { room: String },

    #[serde(rename = "message")]
    Message { room: String, text: String },
}

#[derive(Serialize)]
struct ServerMessage {
    #[serde(flatten)]
    inner: ServerMessageInner,
}

#[derive(Serialize)]
#[serde(tag = "type")]
enum ServerMessageInner {
    #[serde(rename = "joined")]
    Joined { room: String, users: Vec<String> },

    #[serde(rename = "left")]
    Left { room: String },

    #[serde(rename = "message")]
    Message(ChatMessage),

    #[serde(rename = "error")]
    Error { message: String },
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut server = WebSocketServer::new();

    // Track users in rooms
    let room_users: Arc<RwLock<HashMap<String, Vec<String>>>> =
        Arc::new(RwLock::new(HashMap::new()));

    // Handle client messages
    let room_users_clone = Arc::clone(&room_users);
    server.on_message(move |msg: ClientMessage, conn| async move {
        match msg {
            ClientMessage::Join { room, username } => {
                // Set username on connection
                conn.set_metadata("username", &username);
                conn.set_metadata("room", &room);

                // Join room
                let room_obj = server.room(&room);
                room_obj.join(conn.id()).await?;

                // Add to users list
                {
                    let mut users = room_users_clone.write().await;
                    users.entry(room.clone()).or_default().push(username.clone());
                }

                // Get users in room
                let users = {
                    let users_map = room_users_clone.read().await;
                    users_map.get(&room).cloned().unwrap_or_default()
                };

                // Send joined confirmation
                conn.send_json(&ServerMessage {
                    inner: ServerMessageInner::Joined { room, users },
                }).await?;

                // Broadcast user joined
                room_obj.broadcast_filtered(
                    |c| c.id() != conn.id(),
                    &ServerMessage {
                        inner: ServerMessageInner::Message(ChatMessage {
                            room: room_obj.name().to_string(),
                            user: "System".into(),
                            text: format!("{} joined", username),
                            timestamp: now(),
                        }),
                    },
                ).await?;

                println!("{} joined room {}", username, room);
            },

            ClientMessage::Message { room, text } => {
                let username = conn.get_metadata("username")
                    .unwrap_or_else(|| "Anonymous".to_string());

                let room_obj = server.room(&room);

                // Broadcast message to room
                room_obj.broadcast_json(&ServerMessage {
                    inner: ServerMessageInner::Message(ChatMessage {
                        room: room.clone(),
                        user: username.clone(),
                        text,
                        timestamp: now(),
                    }),
                }).await?;

                println!("{} in {}: {}", username, room, text);
            },

            ClientMessage::Leave { room } => {
                let username = conn.get_metadata("username")
                    .unwrap_or_else(|| "Anonymous".to_string());

                let room_obj = server.room(&room);

                // Remove from users list
                {
                    let mut users = room_users_clone.write().await;
                    if let Some(room_users) = users.get_mut(&room) {
                        room_users.retain(|u| u != &username);
                    }
                }

                // Leave room
                room_obj.leave(conn.id()).await?;

                // Broadcast user left
                room_obj.broadcast(&ServerMessage {
                    inner: ServerMessageInner::Message(ChatMessage {
                        room: room.clone(),
                        user: "System".into(),
                        text: format!("{} left", username),
                        timestamp: now(),
                    }),
                }).await?;

                conn.send_json(&ServerMessage {
                    inner: ServerMessageInner::Left { room },
                }).await?;

                println!("{} left room {}", username, room);
            },
        }

        Ok(())
    });

    // Handle disconnect
    let room_users_clone = Arc::clone(&room_users);
    server.on_disconnect(move |info| async move {
        if let Some(conn) = server.get_connection(info.conn_id).await {
            if let (Some(username), Some(room)) = (
                conn.get_metadata("username"),
                conn.get_metadata("room")
            ) {
                // Remove from room
                let mut users = room_users_clone.write().await;
                if let Some(room_users) = users.get_mut(&room) {
                    room_users.retain(|u| u != &username);
                }

                // Leave room
                let room_obj = server.room(&room);
                room_obj.leave(info.conn_id).await?;

                println!("{} disconnected from {}", username, room);
            }
        }
        Ok(())
    });

    println!("Chat Room Server listening on ws://127.0.0.1:8080");
    server.listen("127.0.0.1:8080").await?;

    Ok(())
}

fn now() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_secs() as i64
}
```

