## Example 3: Broadcast Messaging

Server that broadcasts every message to all connected clients.

### examples/broadcast_server.rs

```rust
use serde::{Deserialize, Serialize};
use websocket_rs::WebSocketServer;

#[derive(Serialize, Deserialize)]
struct BroadcastMessage {
    sender: String,
    message: String,
    timestamp: i64,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut server = WebSocketServer::new();

    // Assign ID to each client
    server.on_connect(|_info, conn| async move {
        let client_id = format!("client_{}", conn.id());
        conn.set_metadata("client_id", &client_id);

        println!("{} connected", client_id);

        // Send welcome message
        conn.send_text(&format!("Welcome! Your ID is {}", client_id)).await?;

        Ok(())
    });

    // Broadcast every message to all clients
    server.on_message(|msg: BroadcastMessage| async move {
        println!("Broadcast from {}: {}", msg.sender, msg.message);

        // Broadcast to all
        server.broadcast_json(&msg).await?;

        Ok(())
    });

    // Notify on disconnect
    server.on_disconnect(|info| async move {
        if let Some(conn) = server.get_connection(info.conn_id).await {
            if let Some(client_id) = conn.get_metadata("client_id") {
                println!("{} disconnected", client_id);

                // Notify others
                let notification = BroadcastMessage {
                    sender: "System".into(),
                    message: format!("{} disconnected", client_id),
                    timestamp: now(),
                };

                let _ = server.broadcast_json(&notification).await;
            }
        }

        Ok(())
    });

    println!("Broadcast Server listening on ws://127.0.0.1:8080");
    server.listen("127.0.0.1:8080").await?;

    Ok(())
}

fn now() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
