## Example 4: Room-Based Communication

Organize clients into rooms with targeted messaging.

### examples/room_server.rs

```rust
use serde::{Deserialize, Serialize};
use websocket_rs::WebSocketServer;

#[derive(Serialize, Deserialize)]
#[serde(tag = "action")]
enum RoomMessage {
    #[serde(rename = "create")]
    Create { name: String },

    #[serde(rename = "join")]
    Join { room: String },

    #[serde(rename = "leave")]
    Leave { room: String },

    #[serde(rename = "send")]
    Send { room: String, text: String },

    #[serde(rename = "list")]
    List,
}

#[derive(Serialize)]
struct RoomResponse {
    #[serde(flatten)]
    response: RoomResponseInner,
}

#[derive(Serialize)]
#[serde(tag = "type")]
enum RoomResponseInner {
    #[serde(rename = "created")]
    Created { name: String },

    #[serde(rename = "joined")]
    Joined { room: String, members: u32 },

    #[serde(rename = "left")]
    Left { room: String },

    #[serde(rename = "message")]
    Message { room: String, user: String, text: String },

    #[serde(rename = "rooms")]
    Rooms { rooms: Vec<String> },
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut server = WebSocketServer::new();

    server.on_connect(|_info, conn| async move {
        conn.set_metadata("user", &format!("user_{}", conn.id()));
        Ok(())
    });

    server.on_message(|msg: RoomMessage, conn| async move {
        match msg {
            RoomMessage::Create { name } => {
                server.create_room(&name).await?;

                conn.send_json(&RoomResponse {
                    response: RoomResponseInner::Created { name },
                }).await?;

                println!("Room '{}' created by {}", name, conn.id());
            },

            RoomMessage::Join { room } => {
                let user = conn.get_metadata("user").unwrap_or_default();
                let room_obj = server.room(&room);

                room_obj.join(conn.id()).await?;
                let count = room_obj.count().await;

                conn.send_json(&RoomResponse {
                    response: RoomResponseInner::Joined { room, members: count as u32 },
                }).await?;

                // Announce join
                room_obj.send_to(conn.id(), &format!("Welcome to {}, {}!", room, user)).await?;

                println!("{} joined room {}", user, room);
            },

            RoomMessage::Leave { room } => {
                let user = conn.get_metadata("user").unwrap_or_default();
                let room_obj = server.room(&room);

                room_obj.leave(conn.id()).await?;

                conn.send_json(&RoomResponse {
                    response: RoomResponseInner::Left { room },
                }).await?;

                println!("{} left room {}", user, room);
            },

            RoomMessage::Send { room, text } => {
                let user = conn.get_metadata("user").unwrap_or_default();
                let room_obj = server.room(&room);

                room_obj.broadcast_json(&RoomResponse {
                    response: RoomResponseInner::Message {
                        room: room.clone(),
                        user,
                        text,
                    },
                }).await?;

                println!("Message in {}: {} - {}", room, user, text);
            },

            RoomMessage::List => {
                let rooms = server.list_rooms().await;

                conn.send_json(&RoomResponse {
                    response: RoomResponseInner::Rooms { rooms },
                }).await?;
            },
        }

        Ok(())
    });

    println!("Room Server listening on ws://127.0.0.1:8080");
    server.listen("127.0.0.1:8080").await?;

    Ok(())
}
```

