## Example 5: Authentication with Tokens

JWT-based authentication for WebSocket connections.

### examples/auth_server.rs

```rust
use jsonwebtoken::{decode, encode, DecodingKey, EncodingKey, Header, Validation};
use serde::{Deserialize, Serialize};
use websocket_rs::{WebSocketServer, middleware::Auth};
use std::time::{SystemTime, UNIX_EPOCH};

const JWT_SECRET: &str = "your-secret-key-change-in-production";

#[derive(Serialize, Deserialize)]
struct Claims {
    sub: String,
    exp: usize,
}

#[derive(Serialize, Deserialize)]
struct AuthMessage {
    token: String,
}

fn generate_token(user_id: &str) -> Result<String, Box<dyn std::error::Error>> {
    let expiration = SystemTime::now()
        .duration_since(UNIX_EPOCH)?
        .as_secs() + 3600; // 1 hour

    let claims = Claims {
        sub: user_id.to_string(),
        exp: expiration as usize,
    };

    let token = encode(
        &Header::default(),
        &claims,
        &EncodingKey::from_secret(JWT_SECRET.as_ref()),
    )?;

    Ok(token)
}

fn validate_token(token: &str) -> Result<String, Box<dyn std::error::Error>> {
    let token_data = decode::<Claims>(
        token,
        &DecodingKey::from_secret(JWT_SECRET.as_ref()),
        &Validation::default()
    )?;

    Ok(token_data.claims.sub)
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut server = WebSocketServer::new()
        .with_middleware(
            Auth::new(JWT_SECRET)
                .with_header("Authorization")
                .with_prefix("Bearer ")
        );

    // Handle authenticated messages
    server.on_text(|text: String, conn| async move {
        let user_id = conn.get_metadata("user_id")
            .unwrap_or_else(|| "unknown".to_string());

        println!("User {} says: {}", user_id, text);

        conn.send_text(&format!("Hello, {}!", user_id)).await?;

        Ok(())
    });

    println!("Auth Server listening on ws://127.0.0.1:8080");
    println!("Get token with: curl http://127.0.0.1:8080/token?user=alice");
    println!("Connect with: websocat -H \"Authorization: Bearer <token>\" ws://127.0.0.1:8080");

    server.listen("127.0.0.1:8080").await?;

    Ok(())
}
```

### Token Generation Endpoint (HTTP)

```rust
use warp::Filter;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Token endpoint
    let token_route = warp::path("token")
        .and(warp::query::<HashMap<String, String>>())
        .map(|params: HashMap<String, String>| {
            let user = params.get("user").unwrap_or(&"anonymous".to_string());
            match generate_token(user) {
                Ok(token) => warp::reply::json(&serde_json::json!({
                    "token": token,
                    "user": user
                })),
                Err(e) => warp::reply::with_status(
                    warp::reply::json(&serde_json::json!({"error": e.to_string()})),
                    warp::http::StatusCode::UNAUTHORIZED
                )
            }
        });

    // Start HTTP server for tokens
    tokio::spawn(async move {
        warp::serve(token_route)
            .run(([127, 0, 0, 1], 8080))
            .await;
    });

    // Start WebSocket server
    // ... (same as above)

    Ok(())
}
```

