## Example 6: Automatic Reconnection

Client that automatically reconnects with exponential backoff.

### examples/reconnecting_client.rs

```rust
use websocket_rs::{WebSocketClient, ReconnectStrategy};
use std::time::Duration;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("Connecting to ws://127.0.0.1:8080...");

    let mut client = WebSocketClient::connect("ws://127.0.0.1:8080")
        .with_reconnect(
            ReconnectStrategy::exponential_backoff()
                .initial_delay(Duration::from_secs(1))
                .max_delay(Duration::from_secs(60))
                .multiplier(2.0)
                .max_attempts(None) // Infinite attempts
        )
        .await?;

    // On connect
    client.on_connect(|| {
        println!("Connected to server!");
    });

    // On disconnect
    client.on_disconnect(|| {
        println!("Disconnected from server");
    });

    // On reconnect
    client.on_reconnect(|| {
        println!("Reconnected to server!");
    });

    // On reconnect failed
    client.on_reconnect_failed(|attempt| {
        println!("Reconnect attempt {} failed, retrying...", attempt);
    });

    // Handle messages
    client.on_text(|text: String| async move {
        println!("Received: {}", text);

        // Send echo
        Ok(())
    });

    // Send periodic messages
    let mut client_clone = client.clone();
    tokio::spawn(async move {
        let mut interval = tokio::time::interval(Duration::from_secs(5));
        loop {
            interval.tick().await;

            if client_clone.is_connected() {
                if let Err(e) = client_clone.send("Ping").await {
                    eprintln!("Failed to send: {}", e);
                }
            }
        }
    });

    // Run client
    client.run().await?;

    Ok(())
}
```

### Test with Server that Crashes

```bash
# Terminal 1: Start server
cargo run --example echo_server

# Terminal 2: Run reconnecting client
cargo run --example reconnecting_client

# Terminal 1: Stop server (Ctrl+C)
# Watch client reconnect

# Terminal 1: Restart server
# Watch client automatically reconnect
```

