### Pub/Sub with Channels

```rust
use websocket_rs::WebSocketServer;

#[tokio::main]
async fn main() -> Result<()> {
    let mut server = WebSocketServer::new();

    // Subscribe to channel
    server.subscribe("news:tech", |item: NewsItem| async move {
        println!("Tech news: {}", item.title);
        server.broadcast_json(&item).await?;
        Ok(())
    });

    // Publish to channel
    server.publish_json("news:tech", &NewsItem {
        title: "Rust 1.80 Released".into(),
        url: "https://rust-lang.org".into(),
    }).await?;

    server.listen("127.0.0.1:8080").await?;

    Ok(())
}

#[derive(serde::Serialize)]
struct NewsItem {
    title: String,
    url: String,
}
